INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'en', 'The Basilica of the Annunciation is a Catholic church in Nazareth, Israel. It is one of the largest churches in the Middle East and marks the traditional site where the Archangel Gabriel announced to Mary that she would bear Jesus.', 'The current basilica was built in 1969, designed by Italian architect Giovanni Muzio. It stands over the ruins of earlier Byzantine and Crusader churches. The site has been a place of Christian pilgrimage since ancient times.', 'The church serves the local Catholic community in Nazareth and welcomes pilgrims from around the world. Regular masses are held in multiple languages.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'en', 'The Church of the Nativity in Bethlehem stands over the grotto that Christian tradition has honoured since the 2nd century as the birthplace of Jesus. It is one of the oldest continuously used churches in the world and a UNESCO World Heritage Site.', 'The first basilica was commissioned by Emperor Constantine and his mother Helena around 327 AD. After it was damaged in the 6th century, Emperor Justinian rebuilt it on a larger scale, and much of today''s church dates from that rebuilding. Crusader-era mosaics and painted columns still survive inside.', 'The church is shared by the Greek Orthodox, Roman Catholic (Franciscan) and Armenian Apostolic communities under the historic Status Quo arrangement. Local Christian families of Bethlehem worship here alongside pilgrims from around the world, especially at Christmas.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'en', 'The Church of the Holy Sepulchre in the Old City of Jerusalem contains the two holiest sites of Christianity: Golgotha, where Jesus was crucified, and the tomb where he was buried and rose again, according to tradition.', 'Emperor Constantine built the first church here in the 4th century; it was dedicated in 335 AD. It was destroyed in 1009 and rebuilt in the 11th century, and the Crusaders gave it much of its present form in the 12th century. The Edicule over the tomb was restored in 2016–2017.', 'Care of the church is shared by the Greek Orthodox, Roman Catholic (Franciscan) and Armenian Apostolic churches, with the Coptic, Ethiopian and Syriac Orthodox communities also holding chapels, under the Status Quo of 1852. Its doors are opened each morning by Muslim families who have kept the keys for centuries.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'am', 'የብሥራት ባዚሊካ በእስራኤል፣ ናዝሬት ከተማ የሚገኝ የካቶሊክ ቤተ ክርስቲያን ነው። በመካከለኛው ምሥራቅ ካሉ ትልልቅ አብያተ ክርስቲያናት አንዱ ሲሆን፣ ሊቀ መላእክት ቅዱስ ገብርኤል ለቅድስት ድንግል ማርያም ኢየሱስን እንደምትወልድ ያበሠረበት ስፍራ ነው ተብሎ በትውፊት የሚታመንበትን ቦታ ያመለክታል።', 'አሁን ያለው ባዚሊካ በ1969 እ.ኤ.አ. የተሠራ ሲሆን፣ ንድፉን የሠራው ጣሊያናዊው አርክቴክት ጆቫኒ ሙዚዮ ነው። ባዚሊካው ቀደም ሲል በነበሩ የባይዛንታይን እና የመስቀል ጦረኞች ዘመን አብያተ ክርስቲያናት ፍርስራሾች ላይ ቆሟል። ስፍራው ከጥንት ጀምሮ የክርስቲያኖች የንግደት መዳረሻ ሆኖ ቆይቷል።', 'ቤተ ክርስቲያኑ በናዝሬት የሚገኘውን የአካባቢውን የካቶሊክ ማኅበረሰብ ያገለግላል፤ ከመላው ዓለም የሚመጡ ተሳላሚዎችንም በደስታ ይቀበላል። መደበኛ ቅዳሴዎች በተለያዩ ቋንቋዎች ይቀርባሉ።') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'am', 'በቤተልሔም የሚገኘው የልደት ቤተ ክርስቲያን፣ የክርስትና ትውፊት ከ2ኛው ክፍለ ዘመን ጀምሮ የኢየሱስ የትውልድ ስፍራ አድርጎ በሚያከብረው ዋሻ ላይ ተሠርቷል። ያለማቋረጥ አገልግሎት ላይ ከዋሉ የዓለም ጥንታዊ አብያተ ክርስቲያናት አንዱ ሲሆን፣ በዩኔስኮ የዓለም ቅርስነት የተመዘገበ ስፍራም ነው።', 'የመጀመሪያው ባዚሊካ የተሠራው በ327 እ.ኤ.አ. ገደማ በንጉሠ ነገሥት ቆስጠንጢኖስና በእናቱ በንግሥት እሌኒ ትእዛዝ ነው። በ6ኛው ክፍለ ዘመን ጉዳት ከደረሰበት በኋላ ንጉሠ ነገሥት ዮስጢኒያኖስ በሰፊ መጠን መልሶ ገነባው፤ የዛሬው ቤተ ክርስቲያን አብዛኛው ክፍል የዚያ ዳግም ግንባታ ውጤት ነው። ከመስቀል ጦረኞች ዘመን የተረፉ የሞዛይክ ሥዕሎችና ቀለም የተቀቡ ዓምዶች አሁንም በውስጡ ይገኛሉ።', 'ቤተ ክርስቲያኑን በታሪካዊው የስታተስ ኮ ስምምነት መሠረት የግሪክ ኦርቶዶክስ፣ የሮማ ካቶሊክ (ፍራንቸስኮሳውያን) እና የአርመን ሐዋርያዊት ቤተ ክርስቲያን ማኅበረሰቦች በጋራ ይጠቀሙበታል። የቤተልሔም የአካባቢው ክርስቲያን ቤተሰቦች ከመላው ዓለም ከሚመጡ ተሳላሚዎች ጋር በተለይም በገና በዓል እዚህ ያመልካሉ።') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'am', 'በኢየሩሳሌም አሮጌ ከተማ የሚገኘው የቅዱስ መቃብር ቤተ ክርስቲያን የክርስትናን ሁለቱን እጅግ ቅዱሳት መካናት ይዟል፤ እነርሱም በትውፊት መሠረት ኢየሱስ የተሰቀለበት ጎልጎታ እና የተቀበረበትና ከሙታን የተነሣበት መቃብር ናቸው።', 'ንጉሠ ነገሥት ቆስጠንጢኖስ በዚህ ስፍራ የመጀመሪያውን ቤተ ክርስቲያን በ4ኛው ክፍለ ዘመን አሠራ፤ ቤተ ክርስቲያኑም በ335 እ.ኤ.አ. ተቀደሰ። በ1009 ፈርሶ በ11ኛው ክፍለ ዘመን እንደገና ተገነባ፤ የመስቀል ጦረኞችም በ12ኛው ክፍለ ዘመን አሁን ያለውን ቅርጽ በአብዛኛው ሰጡት። በመቃብሩ ላይ ያለው ትንሽ መቅደስ (ኤዲኩል) በ2016–2017 ታድሷል።', 'የቤተ ክርስቲያኑን እንክብካቤ በ1852ቱ የስታተስ ኮ ስምምነት መሠረት የግሪክ ኦርቶዶክስ፣ የሮማ ካቶሊክ (ፍራንቸስኮሳውያን) እና የአርመን ሐዋርያዊት አብያተ ክርስቲያናት በጋራ ይወጣሉ፤ የቅብጥ ኦርቶዶክስ፣ የኢትዮጵያ ኦርቶዶክስ ተዋሕዶ እና የሶርያ ኦርቶዶክስ ማኅበረሰቦችም የራሳቸው ጸሎት ቤቶች አሏቸው። በሩ በየማለዳው የሚከፈተው ቁልፎቹን ለዘመናት ሲጠብቁ በኖሩ ሙስሊም ቤተሰቦች ነው።') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
