INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'ba05a1f8-57a8-428d-955b-849cafe8e2d7', 'content', 'am', 'በልዩ የገና ቅዳሴዎችና የበዓል ሥርዓቶች ላይ አብረውን ይሳተፉ። መርሐ ግብሩን በድረ ገጻችን ላይ ማግኘት ይችላሉ።', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
