INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_visiting_info', '34a96c2a-68fd-4a37-8df7-ede5a4d02b7e', 'admission_info', 'am', 'መግቢያ በነጻ ነው። ተገቢ አለባበስ ግዴታ ነው።', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
