INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'am', 'እድሳት', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'am', 'ይህ ፕሮጀክት በባዚሊካው አስቸኳይ የእድሳት ፍላጎቶች ላይ ያተኩራል፤ ከእነዚህም መካከል የመዋቅር ጥገና፣ የፊት ገጽታ ጽዳት እና የመጀመሪያዎቹን የሥነ ሕንጻ ክፍሎች መጠበቅ ይገኙበታል። ሥራው ሕንጻው ለመጪው ትውልድ ደኅንነቱ የተጠበቀና ተደራሽ ሆኖ እንዲቀጥል ያደርጋል።', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'am', 'የብሥራት ባዚሊካ ዋና አዳራሽና የፊት ገጽታ እድሳት።', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'am', 'የባዚሊካው እድሳት - ምዕራፍ 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
