INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ar', 'كنيسة البشارة هي كنيسة كاثوليكية تقع في الناصرة، إسرائيل. وهي واحدة من أكبر الكنائس في الشرق الأوسط وتحتفل بالموقع التقليدي حيث بشّر الملاك جبرائيل مريم بأنها ستلد يسوع.', 'تم بناء البازيليكا الحالية عام 1969، صممها المهندس المعماري الإيطالي جيوفاني موتسيو. تقف على أنقاض كنائس بيزنطية وصليبية سابقة. كان الموقع مكانًا للحج المسيحي منذ العصور القديمة.', 'تخدم الكنيسة المجتمع الكاثوليكي المحلي في الناصرة وترحب بالحجاج من جميع أنحاء العالم. تقام القداس بانتظام بلغات متعددة.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ar', 'تقوم كنيسة المهد في بيت لحم فوق المغارة التي يُكرّمها التقليد المسيحي منذ القرن الثاني باعتبارها مكان ولادة يسوع المسيح. وهي واحدة من أقدم الكنائس التي لا تزال قيد الاستخدام المستمر في العالم، وموقع مدرج على لائحة التراث العالمي لليونسكو.', 'أمر الإمبراطور قسطنطين ووالدته هيلانة ببناء البازيليكا الأولى حوالي عام 327 م. وبعد أن تضررت في القرن السادس، أعاد الإمبراطور جستنيان بناءها على نطاق أوسع، ويعود جزء كبير من الكنيسة الحالية إلى ذلك البناء. لا تزال الفسيفساء والأعمدة المرسومة من العصر الصليبي باقية في الداخل.', 'تشترك في الكنيسة طوائف الروم الأرثوذكس والكاثوليك (الفرنسيسكان) والأرمن الأرثوذكس بموجب ترتيب الوضع الراهن التاريخي. تصلي فيها عائلات بيت لحم المسيحية المحلية جنبًا إلى جنب مع الحجاج القادمين من جميع أنحاء العالم، خاصة في عيد الميلاد.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ar', 'تضم كنيسة القيامة في البلدة القديمة بالقدس أقدس موقعين في المسيحية: الجلجثة، حيث صُلب يسوع، والقبر الذي دُفن فيه وقام منه، بحسب التقليد.', 'بنى الإمبراطور قسطنطين الكنيسة الأولى هنا في القرن الرابع، وكُرِّست عام 335 م. دُمِّرت عام 1009 وأُعيد بناؤها في القرن الحادي عشر، ومنحها الصليبيون معظم شكلها الحالي في القرن الثاني عشر. رُمِّم الإيديكول (الكنيسة الصغيرة) فوق القبر بين عامي 2016 و2017.', 'تتشارك في رعاية الكنيسة طوائف الروم الأرثوذكس والكاثوليك (الفرنسيسكان) والأرمن الأرثوذكس، كما تحتفظ الطوائف القبطية والإثيوبية والسريانية الأرثوذكسية بمصليات فيها، وذلك بموجب الوضع الراهن لعام 1852. تُفتح أبوابها كل صباح على يد عائلات مسلمة تحافظ على مفاتيحها منذ قرون.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
