INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'bg', 'Базиликата на Благовещение е католическа църква в Назарет, Израел. Тя е една от най-големите църкви в Близкия изток и отбелязва мястото, което според преданието е там, където архангел Гавраил възвестил на Мария, че ще роди Иисус.', 'Днешната базилика е построена през 1969 г. по проект на италианския архитект Джовани Муцио. Тя се издига над руините на по-ранни византийски и кръстоносни църкви. Мястото е средище на християнски поклонения от древни времена.', 'Църквата служи на местната католическа общност в Назарет и посреща поклонници от цял свят. Литургии се отслужват редовно на няколко езика.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'bg', 'Църквата на Рождество Христово във Витлеем се издига над пещерата, която християнската традиция от 2 век почита като място на раждането на Иисус. Тя е една от най-старите непрекъснато използвани църкви в света и обект на световното наследство на ЮНЕСКО.', 'Първата базилика е построена около 327 г. по поръка на император Константин и майка му Елена. След като е повредена през 6 век, император Юстиниан я възстановява в по-голям мащаб и голяма част от днешната църква е от това възстановяване. Вътре все още са запазени мозайки и изписани колони от епохата на кръстоносците.', 'Църквата е поделена между гръцката православна, римокатолическата (францисканска) и арменската апостолическа общност съгласно историческото статукво. Местните християнски семейства от Витлеем се молят тук заедно с поклонници от цял свят, особено по Коледа.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'bg', 'Църквата на Божи гроб в Стария град на Йерусалим съдържа двете най-свети места на християнството: Голгота, където Иисус е разпнат, и гроба, в който според преданието е погребан и възкръснал.', 'Император Константин построява първата църква тук през 4 век; тя е осветена през 335 г. Разрушена е през 1009 г. и възстановена през 11 век, а кръстоносците ѝ придават голяма част от днешния облик през 12 век. Едикулата над гроба е реставрирана през 2016–2017 г.', 'Грижата за църквата е поделена между гръцката православна, римокатолическата (францисканска) и арменската апостолическа църква, като коптската, етиопската и сирийската православна общност също имат параклиси, съгласно статуквото от 1852 г. Вратите ѝ се отварят всяка сутрин от мюсюлмански семейства, които пазят ключовете от векове.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
