INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'bg', 'Реставрация', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'bg', 'Този проект е насочен към неотложните нужди от реставрация на базиликата, включително конструктивни ремонти, почистване на фасадата и опазване на оригиналните архитектурни елементи. Работата ще гарантира, че сградата ще остане безопасна и достъпна за бъдещите поколения.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'bg', 'Реставрация на главния кораб и фасадата на Базиликата на Благовещение.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'bg', 'Реставрация на базиликата — етап 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'bg', 'Документиране', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'bg', 'Мащабна инициатива за фотографиране, сканиране и документиране на обекти на християнското наследство, артефакти и ръкописи из Израел и съседните региони. Този дигитален архив ще съхрани безценни исторически свидетелства за изследователите и бъдещите поколения.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'bg', 'Дигитално документиране на обекти на християнското наследство из цялата Света земя.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'bg', 'Документиране на наследството на Светата земя', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'cs', 'Bazilika Zvěstování je katolický kostel v Nazaretu v Izraeli. Je jedním z největších kostelů na Blízkém východě a označuje tradiční místo, kde archanděl Gabriel zvěstoval Marii, že porodí Ježíše.', 'Současná bazilika byla postavena v roce 1969 podle návrhu italského architekta Giovanniho Muzia. Stojí nad ruinami dřívějších byzantských a křižáckých kostelů. Toto místo je cílem křesťanských poutí již od starověku.', 'Kostel slouží místní katolické komunitě v Nazaretu a vítá poutníky z celého světa. Pravidelně se zde konají mše v několika jazycích.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'cs', 'Bazilika Narození Páně v Betlémě stojí nad jeskyní, kterou křesťanská tradice od 2. století uctívá jako místo narození Ježíše. Je jedním z nejstarších nepřetržitě užívaných kostelů na světě a je zapsána na seznamu světového dědictví UNESCO.', 'První baziliku nechal kolem roku 327 n. l. postavit císař Konstantin a jeho matka Helena. Poté, co byla v 6. století poškozena, ji císař Justinián nechal přestavět ve větším rozsahu a velká část dnešního kostela pochází z této přestavby. Uvnitř se dodnes dochovaly mozaiky a malované sloupy z křižácké doby.', 'Kostel sdílejí řecká pravoslavná, římskokatolická (františkánská) a arménská apoštolská komunita v rámci historického uspořádání status quo. Místní křesťanské rodiny z Betléma se zde modlí společně s poutníky z celého světa, zejména o Vánocích.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'cs', 'Bazilika Božího hrobu ve Starém Městě v Jeruzalémě zahrnuje dvě nejsvětější místa křesťanství: Golgotu, kde byl Ježíš ukřižován, a hrob, do něhož byl podle tradice pohřben a z něhož vstal z mrtvých.', 'Císař Konstantin zde ve 4. století nechal postavit první kostel; ten byl vysvěcen v roce 335 n. l. Byl zničen v roce 1009 a v 11. století obnoven, přičemž křižáci mu ve 12. století dali z velké části jeho dnešní podobu. Edikula nad hrobem byla obnovena v letech 2016–2017.', 'Péči o kostel sdílejí řecká pravoslavná, římskokatolická (františkánská) a arménská apoštolská církev, přičemž koptská, etiopská a syrská pravoslavná komunita zde rovněž mají kaple, v souladu se status quo z roku 1852. Jeho dveře každé ráno otevírají muslimské rodiny, které klíče opatrují po staletí.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
