INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'cs', 'Obnova', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'cs', 'Tento projekt se zaměřuje na naléhavé potřeby obnovy baziliky, včetně stavebních oprav, čištění průčelí a zachování původních architektonických prvků. Práce zajistí, aby budova zůstala bezpečná a přístupná pro budoucí generace.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'cs', 'Obnova hlavní lodi a průčelí Baziliky Zvěstování.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'cs', 'Obnova baziliky – fáze 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'cs', 'Dokumentace', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'cs', 'Komplexní iniciativa zaměřená na fotografování, skenování a dokumentaci křesťanských památkových míst, artefaktů a rukopisů v Izraeli a okolních regionech. Tento digitální archiv uchová neocenitelné historické záznamy pro badatele a budoucí generace.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'cs', 'Digitální dokumentace křesťanských památkových míst po celé Svaté zemi.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'cs', 'Dokumentace dědictví Svaté země', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'de', 'Die Verkündigungsbasilika ist eine katholische Kirche in Nazareth, Israel. Sie ist eine der größten Kirchen im Nahen Osten und markiert den traditionellen Ort, an dem der Erzengel Gabriel Maria verkündete, dass sie Jesus gebären würde.', 'Die heutige Basilika wurde 1969 nach Plänen des italienischen Architekten Giovanni Muzio errichtet. Sie erhebt sich über den Ruinen früherer byzantinischer und kreuzfahrerzeitlicher Kirchen. Der Ort ist seit der Antike ein Ziel christlicher Pilgerfahrten.', 'Die Kirche dient der örtlichen katholischen Gemeinde in Nazareth und heißt Pilger aus aller Welt willkommen. Regelmäßige Messen werden in mehreren Sprachen gefeiert.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'de', 'Die Geburtskirche in Bethlehem erhebt sich über der Grotte, die die christliche Tradition seit dem 2. Jahrhundert als Geburtsort Jesu verehrt. Sie ist eine der ältesten durchgehend genutzten Kirchen der Welt und eine UNESCO-Welterbestätte.', 'Die erste Basilika wurde um 327 n. Chr. von Kaiser Konstantin und seiner Mutter Helena in Auftrag gegeben. Nachdem sie im 6. Jahrhundert beschädigt worden war, ließ Kaiser Justinian sie in größerem Maßstab wiederaufbauen, und ein Großteil der heutigen Kirche stammt aus diesem Wiederaufbau. Mosaiken und bemalte Säulen aus der Kreuzfahrerzeit sind im Inneren noch erhalten.', 'Die Kirche wird von der griechisch-orthodoxen, der römisch-katholischen (franziskanischen) und der armenisch-apostolischen Gemeinschaft im Rahmen der historischen Status-quo-Regelung gemeinsam genutzt. Örtliche christliche Familien aus Bethlehem beten hier gemeinsam mit Pilgern aus aller Welt, besonders zu Weihnachten.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'de', 'Die Grabeskirche in der Altstadt von Jerusalem umfasst die beiden heiligsten Stätten des Christentums: Golgatha, wo Jesus gekreuzigt wurde, und das Grab, in dem er der Überlieferung nach bestattet wurde und auferstand.', 'Kaiser Konstantin ließ hier im 4. Jahrhundert die erste Kirche errichten; sie wurde 335 n. Chr. geweiht. Sie wurde 1009 zerstört und im 11. Jahrhundert wiederaufgebaut, und die Kreuzfahrer gaben ihr im 12. Jahrhundert weitgehend ihre heutige Form. Die Ädikula über dem Grab wurde 2016–2017 restauriert.', 'Die Pflege der Kirche teilen sich die griechisch-orthodoxe, die römisch-katholische (franziskanische) und die armenisch-apostolische Kirche, während die koptische, äthiopische und syrisch-orthodoxe Gemeinschaft ebenfalls Kapellen unterhalten, gemäß dem Status quo von 1852. Ihre Türen werden jeden Morgen von muslimischen Familien geöffnet, die seit Jahrhunderten die Schlüssel bewahren.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
