INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', '593f2031-2c23-4d15-86c5-7487a8296b4f', 'content', 'de', 'Die Phase der statischen Begutachtung wurde erfolgreich abgeschlossen. Ingenieure haben die wichtigsten Bereiche identifiziert, die Aufmerksamkeit erfordern.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
