INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'de', 'Restaurierung', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'de', 'Dieses Projekt konzentriert sich auf die dringendsten Restaurierungsbedürfnisse der Basilika, einschließlich struktureller Reparaturen, der Reinigung der Fassade und der Bewahrung originaler architektonischer Elemente. Die Arbeiten werden sicherstellen, dass das Gebäude für künftige Generationen sicher und zugänglich bleibt.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'de', 'Restaurierung des Hauptschiffs und der Fassade der Verkündigungsbasilika.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'de', 'Restaurierung der Basilika – Phase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'de', 'Dokumentation', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'de', 'Eine umfassende Initiative zur Fotografie, Digitalisierung und Dokumentation christlicher Erbestätten, Artefakte und Manuskripte in Israel und den umliegenden Regionen. Dieses digitale Archiv wird unschätzbare historische Aufzeichnungen für Forscher und künftige Generationen bewahren.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'de', 'Digitale Dokumentation christlicher Erbestätten im gesamten Heiligen Land.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'de', 'Dokumentation des Erbes des Heiligen Landes', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'el', 'Η Βασιλική του Ευαγγελισμού είναι καθολικός ναός στη Ναζαρέτ του Ισραήλ. Είναι ένας από τους μεγαλύτερους ναούς στη Μέση Ανατολή και σηματοδοτεί τον παραδοσιακό τόπο όπου ο Αρχάγγελος Γαβριήλ ανήγγειλε στη Μαρία ότι θα γεννούσε τον Ιησού.', 'Η σημερινή βασιλική χτίστηκε το 1969, σχεδιασμένη από τον Ιταλό αρχιτέκτονα Τζιοβάνι Μούτζιο. Υψώνεται πάνω από τα ερείπια παλαιότερων βυζαντινών ναών και ναών της εποχής των Σταυροφοριών. Ο τόπος αποτελεί προορισμό χριστιανικού προσκυνήματος από τους αρχαίους χρόνους.', 'Ο ναός εξυπηρετεί την τοπική καθολική κοινότητα της Ναζαρέτ και υποδέχεται προσκυνητές από όλο τον κόσμο. Τακτικές λειτουργίες τελούνται σε πολλές γλώσσες.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'el', 'Ο Ναός της Γεννήσεως στη Βηθλεέμ υψώνεται πάνω από το σπήλαιο που η χριστιανική παράδοση τιμά από τον 2ο αιώνα ως τον τόπο γέννησης του Ιησού. Είναι ένας από τους παλαιότερους ναούς σε συνεχή χρήση στον κόσμο και Μνημείο Παγκόσμιας Κληρονομιάς της UNESCO.', 'Η πρώτη βασιλική ανεγέρθηκε κατ'' εντολή του αυτοκράτορα Κωνσταντίνου και της μητέρας του Ελένης γύρω στο 327 μ.Χ. Αφού υπέστη ζημιές τον 6ο αιώνα, ο αυτοκράτορας Ιουστινιανός την ανοικοδόμησε σε μεγαλύτερη κλίμακα, και μεγάλο μέρος του σημερινού ναού χρονολογείται από εκείνη την ανοικοδόμηση. Ψηφιδωτά και ζωγραφισμένοι κίονες της εποχής των Σταυροφοριών σώζονται ακόμη στο εσωτερικό.', 'Ο ναός μοιράζεται μεταξύ των κοινοτήτων των Ελληνορθόδοξων, των Ρωμαιοκαθολικών (Φραγκισκανών) και των Αρμενίων Αποστολικών, σύμφωνα με την ιστορική συμφωνία του Καθεστώτος Status Quo. Οι τοπικές χριστιανικές οικογένειες της Βηθλεέμ προσεύχονται εδώ μαζί με προσκυνητές από όλο τον κόσμο, ιδίως τα Χριστούγεννα.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'el', 'Ο Ναός της Αναστάσεως στην Παλιά Πόλη της Ιερουσαλήμ περιλαμβάνει τους δύο ιερότερους τόπους του Χριστιανισμού: τον Γολγοθά, όπου σταυρώθηκε ο Ιησούς, και τον τάφο όπου, σύμφωνα με την παράδοση, ενταφιάστηκε και αναστήθηκε.', 'Ο αυτοκράτορας Κωνσταντίνος έχτισε εδώ τον πρώτο ναό τον 4ο αιώνα· τα εγκαίνιά του τελέστηκαν το 335 μ.Χ. Καταστράφηκε το 1009 και ανοικοδομήθηκε τον 11ο αιώνα, ενώ οι Σταυροφόροι του έδωσαν σε μεγάλο βαθμό τη σημερινή του μορφή τον 12ο αιώνα. Το Κουβούκλιο πάνω από τον Τάφο αναστηλώθηκε το 2016–2017.', 'Τη φροντίδα του ναού μοιράζονται οι Ελληνορθόδοξοι, οι Ρωμαιοκαθολικοί (Φραγκισκανοί) και οι Αρμένιοι Αποστολικοί, ενώ οι κοπτική, αιθιοπική και συριακή ορθόδοξη κοινότητα διατηρούν επίσης δικά τους παρεκκλήσια, σύμφωνα με το Καθεστώς Status Quo του 1852. Οι πύλες του ανοίγουν κάθε πρωί από μουσουλμανικές οικογένειες που φυλάσσουν τα κλειδιά επί αιώνες.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
