INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'es', 'Restauración', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'es', 'Este proyecto se centra en las necesidades críticas de restauración de la basílica, incluidas las reparaciones estructurales, la limpieza de la fachada y la conservación de los elementos arquitectónicos originales. Este trabajo garantizará que el edificio siga siendo seguro y accesible para las generaciones futuras.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'es', 'Restauración de la nave principal y la fachada de la Basílica de la Anunciación.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'es', 'Restauración de la basílica - Fase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'es', 'Documentación', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'es', 'Una iniciativa integral para fotografiar, escanear y documentar sitios, objetos y manuscritos del patrimonio cristiano en Israel y las regiones circundantes. Este archivo digital preservará registros históricos de valor incalculable para investigadores y para las generaciones futuras.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'es', 'Documentación digital de los sitios del patrimonio cristiano en toda Tierra Santa.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'es', 'Documentación del patrimonio de Tierra Santa', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'fil', 'Ang Basilika ng Pagpapahayag ay isang simbahang Katoliko sa Nazaret, Israel. Isa ito sa pinakamalaking simbahan sa Gitnang Silangan at minamarkahan nito ang tradisyunal na pook kung saan ipinahayag ng Arkanghel Gabriel kay Maria na siya ay magsisilang kay Hesus.', 'Ang kasalukuyang basilika ay itinayo noong 1969, na dinisenyo ng arkitektong Italyano na si Giovanni Muzio. Nakatayo ito sa ibabaw ng mga guho ng mas naunang mga simbahang Bizantino at Krusada. Ang pook na ito ay naging lugar ng peregrinasyong Kristiyano mula pa noong sinaunang panahon.', 'Naglilingkod ang simbahan sa lokal na komunidad na Katoliko ng Nazaret at tumatanggap ng mga peregrino mula sa buong mundo. Regular na nagdaraos ng Misa sa iba''t ibang wika.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'fil', 'Ang Simbahan ng Kapanganakan sa Betlehem ay nakatayo sa ibabaw ng yungib na itinuturing ng tradisyong Kristiyano mula pa noong ika-2 siglo bilang lugar ng kapanganakan ni Hesus. Isa ito sa mga pinakamatandang simbahan na patuloy na ginagamit sa buong mundo at itinalagang Pandaigdigang Pamanang Pook ng UNESCO.', 'Ang unang basilika ay ipinatayo ni Emperador Constantino at ng kanyang ina na si Helena noong mga 327 AD. Matapos masira noong ika-6 na siglo, muling itinayo ito ni Emperador Justiniano sa mas malaking sukat, at karamihan sa kasalukuyang simbahan ay mula sa rekonstruksyong iyon. Buhay pa rin ang mga mosaiko at pintadong haligi mula sa panahon ng mga Krusada sa loob ng simbahan.', 'Ang simbahan ay pinaghahatian ng mga komunidad na Griyegong Ortodokso, Romano Katoliko (Pransiskano), at Armenyong Apostoliko sa ilalim ng makasaysayang kasunduang Status Quo. Ang mga lokal na pamilyang Kristiyano ng Betlehem ay sumasamba dito kasama ang mga peregrino mula sa buong mundo, lalo na tuwing Pasko.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'fil', 'Ang Simbahan ng Banal na Libingan sa Lumang Lungsod ng Jerusalem ay naglalaman ng dalawang pinakabanal na pook ng Kristiyanismo: ang Golgota, kung saan ipinako sa krus si Hesus, at ang libingan kung saan siya inilibing at nabuhay muli, ayon sa tradisyon.', 'Itinayo ni Emperador Constantino ang unang simbahan dito noong ika-4 na siglo; itinalaga ito noong 335 AD. Nawasak ito noong 1009 at muling itinayo noong ika-11 siglo, at binigyan ito ng mga Krusador ng malaki sa kasalukuyang anyo nito noong ika-12 siglo. Ang Edikulo sa ibabaw ng libingan ay isinaayos noong 2016–2017.', 'Ang pangangalaga sa simbahan ay pinaghahatian ng mga simbahang Griyegong Ortodokso, Romano Katoliko (Pransiskano), at Armenyong Apostoliko, kasama ang mga komunidad na Kopto, Etiope, at Siriakong Ortodokso na may sari-sariling kapilya, sa ilalim ng Status Quo ng 1852. Binubuksan ang mga pinto nito tuwing umaga ng mga pamilyang Muslim na nag-iingat ng mga susi sa loob ng mga siglo.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
