INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'fil', 'Restorasyon', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'fil', 'Nakatuon ang proyektong ito sa kritikal na pangangailangan sa restorasyon ng basilika, kasama ang pagkukumpuni ng estruktura, paglilinis ng harapan, at pangangalaga ng orihinal na mga elemento ng arkitektura. Tiyakin ng gawaing ito na mananatiling ligtas at naa-access ang gusali para sa susunod na henerasyon.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'fil', 'Restorasyon ng pangunahing nave at harapan ng Basilika ng Pagpapahayag.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'fil', 'Restorasyon ng Basilika - Yugto 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'fil', 'Dokumentasyon', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'fil', 'Isang komprehensibong inisyatiba upang kunan ng larawan, i-scan, at idokumento ang mga pook-pamana, labi, at manuskrito ng mga Kristiyano sa buong Israel at karatig na rehiyon. Pangangalagaan ng digital na arkibo na ito ang napakahalagang tala pangkasaysayan para sa mga mananaliksik at susunod na henerasyon.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'fil', 'Digital na dokumentasyon ng mga pook-pamana ng mga Kristiyano sa buong Banal na Lupain.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'fil', 'Dokumentasyon ng Pamana sa Banal na Lupain', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'fr', 'La Basilique de l''Annonciation est une église catholique de Nazareth, en Israël. C''est l''une des plus grandes églises du Moyen-Orient, et elle marque le lieu traditionnel où l''archange Gabriel annonça à Marie qu''elle enfanterait Jésus.', 'La basilique actuelle a été construite en 1969, selon les plans de l''architecte italien Giovanni Muzio. Elle s''élève au-dessus des vestiges d''églises byzantines et croisées antérieures. Le site est un lieu de pèlerinage chrétien depuis l''Antiquité.', 'L''église sert la communauté catholique locale de Nazareth et accueille des pèlerins du monde entier. Des messes régulières y sont célébrées en plusieurs langues.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'fr', 'La Basilique de la Nativité, à Bethléem, s''élève au-dessus de la grotte que la tradition chrétienne honore depuis le IIe siècle comme le lieu de naissance de Jésus. C''est l''une des plus anciennes églises en usage continu au monde et un site du patrimoine mondial de l''UNESCO.', 'La première basilique fut commandée par l''empereur Constantin et sa mère Hélène vers 327 apr. J.-C. Après avoir été endommagée au VIe siècle, l''empereur Justinien la reconstruisit à plus grande échelle, et une grande partie de l''église actuelle date de cette reconstruction. Des mosaïques et des colonnes peintes de l''époque des Croisades subsistent encore à l''intérieur.', 'L''église est partagée par les communautés grecque orthodoxe, catholique romaine (franciscaine) et apostolique arménienne selon l''accord historique du Statu quo. Les familles chrétiennes locales de Bethléem y prient aux côtés de pèlerins venus du monde entier, en particulier à Noël.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'fr', 'L''Église du Saint-Sépulcre, dans la vieille ville de Jérusalem, renferme les deux lieux les plus sacrés du christianisme : le Golgotha, où Jésus fut crucifié, et le tombeau où, selon la tradition, il fut enseveli puis ressuscita.', 'L''empereur Constantin fit construire la première église sur ce site au IVe siècle ; elle fut consacrée en 335 apr. J.-C. Détruite en 1009, elle fut reconstruite au XIe siècle, et les croisés lui donnèrent l''essentiel de sa forme actuelle au XIIe siècle. L''édicule surmontant le tombeau a été restauré entre 2016 et 2017.', 'L''entretien de l''église est partagé par les Églises grecque orthodoxe, catholique romaine (franciscaine) et apostolique arménienne, tandis que les communautés copte, éthiopienne et syriaque orthodoxe possèdent également leurs propres chapelles, conformément au Statu quo de 1852. Ses portes sont ouvertes chaque matin par des familles musulmanes qui en gardent les clés depuis des siècles.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
