INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'fr', 'Restauration', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'fr', 'Ce projet porte sur les besoins essentiels de restauration de la basilique, notamment les réparations structurelles, le nettoyage de la façade et la préservation des éléments architecturaux d''origine. Ces travaux garantiront que le bâtiment reste sûr et accessible pour les générations futures.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'fr', 'Restauration de la nef principale et de la façade de la Basilique de l''Annonciation.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'fr', 'Restauration de la basilique - Phase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'fr', 'Documentation', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'fr', 'Une initiative d''envergure visant à photographier, numériser et documenter les sites, objets et manuscrits du patrimoine chrétien en Israël et dans les régions environnantes. Cette archive numérique préservera des documents historiques inestimables pour les chercheurs et pour les générations futures.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'fr', 'Documentation numérique des sites du patrimoine chrétien à travers toute la Terre Sainte.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'fr', 'Documentation du patrimoine de Terre Sainte', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'he', 'בזיליקת הבשורה היא כנסייה קתולית בנצרת, ישראל. זוהי אחת הכנסיות הגדולות במזרח התיכון ומציינת את המקום המסורתי שבו בישר המלאך גבריאל למרים שהיא תלד את ישו.', 'הבזיליקה הנוכחית נבנתה ב-1969, בתכנון האדריכל האיטלקי ג''ובאני מוציו. היא ניצבת על חורבות כנסיות ביזנטיות וצלבניות קודמות. האתר היה מקום עלייה לרגל נוצרי מאז ימי קדם.', 'הכנסייה משרתת את הקהילה הקתולית המקומית בנצרת ומקבלת בברכה עולי רגל מכל רחבי העולם. מיסות מתקיימות באופן קבוע בשפות מרובות.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'he', 'כנסיית המולד בבית לחם ניצבת מעל המערה שהמסורת הנוצרית מכבדת מאז המאה ה-2 כמקום הולדתו של ישוע. זוהי אחת הכנסיות העתיקות ביותר הפועלות ברציפות בעולם, ואתר מורשת עולמית של אונסק"ו.', 'הבזיליקה הראשונה נבנתה ביוזמת הקיסר קונסטנטינוס ואמו הלנה בסביבות שנת 327 לספירה. לאחר שניזוקה במאה ה-6, שיקם אותה הקיסר יוסטיניאנוס בקנה מידה גדול יותר, וחלק ניכר מהכנסייה של היום מקורו בבנייה מחדש זו. פסיפסים ועמודים מצוירים מתקופת הצלבנים עדיין שרדו בפנים.', 'הכנסייה משותפת לקהילות היוונית-אורתודוקסית, הקתולית (הפרנציסקנית) והארמנית-אפוסטולית, במסגרת הסדר הסטטוס קוו ההיסטורי. משפחות נוצריות מקומיות מבית לחם מתפללות בה לצד עולי רגל מכל רחבי העולם, במיוחד בחג המולד.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'he', 'כנסיית הקבר בעיר העתיקה בירושלים כוללת את שני האתרים הקדושים ביותר בנצרות: גולגותא, שבה נצלב ישוע, והקבר שבו נקבר וקם לתחייה, לפי המסורת.', 'הקיסר קונסטנטינוס בנה כאן את הכנסייה הראשונה במאה ה-4; היא הוקדשה בשנת 335 לספירה. היא נהרסה בשנת 1009 ונבנתה מחדש במאה ה-11, והצלבנים העניקו לה את רוב צורתה הנוכחית במאה ה-12. האדיקולה שמעל הקבר שוחזרה בשנים 2016–2017.', 'הטיפול בכנסייה משותף לכנסיות היוונית-אורתודוקסית, הקתולית (הפרנציסקנית) והארמנית-אפוסטולית, כאשר גם לקהילות הקופטית, האתיופית והסורית-אורתודוקסית יש בה קפלות, במסגרת הסטטוס קוו משנת 1852. דלתותיה נפתחות מדי בוקר בידי משפחות מוסלמיות ששומרות על מפתחותיה במשך מאות שנים.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
