INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'he', 'שיקום', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'he', 'פרויקט זה מתמקד בצרכי השיקום הקריטיים של הבזיליקה, לרבות תיקונים קונסטרוקטיביים, ניקוי החזית ושימור האלמנטים האדריכליים המקוריים. העבודה תבטיח שהמבנה יישאר בטוח ונגיש לדורות הבאים.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'he', 'שיקום האולם המרכזי והחזית של בזיליקת הבשורה.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'he', 'שיקום הבזיליקה - שלב 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'he', 'תיעוד', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'he', 'יוזמה מקיפה לצילום, סריקה ותיעוד של אתרי מורשת נוצרית, ממצאים וכתבי יד ברחבי ישראל והאזורים הסובבים. הארכיון הדיגיטלי הזה ישמר תיעוד היסטורי יקר ערך עבור חוקרים ולדורות הבאים.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'he', 'תיעוד דיגיטלי של אתרי מורשת נוצרית ברחבי ארץ הקודש.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'he', 'תיעוד מורשת ארץ הקודש', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'hi', 'घोषणा का महागिरजाघर इस्राएल के नासरत नगर में स्थित एक कैथोलिक गिरजाघर है। यह मध्य पूर्व के सबसे बड़े गिरजाघरों में से एक है और उस पारंपरिक स्थान को चिह्नित करता है जहाँ महादूत जिब्राईल ने मरियम को यह शुभ संदेश दिया था कि वह यीशु को जन्म देंगी।', 'वर्तमान महागिरजाघर 1969 में बनाया गया था और इसकी रूपरेखा इतालवी वास्तुकार जोवान्नी मूत्सियो ने तैयार की थी। यह पहले के बाइज़ेंटाइन और क्रूसेडर-कालीन गिरजाघरों के खंडहरों के ऊपर खड़ा है। यह स्थल प्राचीन काल से ही मसीही तीर्थयात्रा का केंद्र रहा है।', 'यह गिरजाघर नासरत के स्थानीय कैथोलिक समुदाय की सेवा करता है और दुनिया भर से आने वाले तीर्थयात्रियों का स्वागत करता है। यहाँ नियमित रूप से कई भाषाओं में मिस्सा अर्पित किया जाता है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'hi', 'बेथलहम में स्थित जन्म का गिरजाघर उस गुफा के ऊपर बना है जिसे मसीही परंपरा दूसरी शताब्दी से यीशु के जन्मस्थान के रूप में आदर देती आई है। यह दुनिया के उन सबसे प्राचीन गिरजाघरों में से एक है जिनका उपयोग बिना रुके होता आया है, और यह यूनेस्को का विश्व धरोहर स्थल भी है।', 'पहले महागिरजाघर का निर्माण सम्राट कॉन्स्टेंटाइन और उनकी माता हेलेना ने लगभग 327 ईस्वी में करवाया था। छठी शताब्दी में क्षतिग्रस्त होने के बाद सम्राट जस्टिनियन ने इसे और बड़े पैमाने पर दोबारा बनवाया, और आज के गिरजाघर का अधिकांश भाग उसी पुनर्निर्माण के समय का है। क्रूसेडर काल के मोज़ेक और चित्रित स्तंभ आज भी भीतर सुरक्षित हैं।', 'ऐतिहासिक यथास्थिति (स्टेटस क्वो) व्यवस्था के अंतर्गत यह गिरजाघर यूनानी ऑर्थोडॉक्स, रोमन कैथोलिक (फ़्रांसिस्कन) और आर्मेनियाई प्रेरितिक समुदायों द्वारा साझा किया जाता है। बेथलहम के स्थानीय मसीही परिवार दुनिया भर से आए तीर्थयात्रियों के साथ, विशेषकर क्रिसमस के समय, यहाँ आराधना करते हैं।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'hi', 'यरूशलेम के पुराने शहर में स्थित पवित्र कब्र के गिरजाघर में मसीही धर्म के दो सबसे पवित्र स्थल हैं: गुलगुता, जहाँ यीशु को क्रूस पर चढ़ाया गया था, और वह कब्र, जहाँ परंपरा के अनुसार उन्हें दफ़नाया गया और जहाँ से वे फिर जी उठे।', 'सम्राट कॉन्स्टेंटाइन ने चौथी शताब्दी में यहाँ पहला गिरजाघर बनवाया, जिसका प्रतिष्ठापन 335 ईस्वी में हुआ। 1009 में इसे नष्ट कर दिया गया और 11वीं शताब्दी में इसका पुनर्निर्माण हुआ; 12वीं शताब्दी में क्रूसेडरों ने इसे वह रूप दिया जो आज अधिकांशतः दिखाई देता है। कब्र के ऊपर बने छोटे पवित्र कक्ष (एडिक्यूल) का जीर्णोद्धार 2016–2017 में किया गया।', '1852 की यथास्थिति (स्टेटस क्वो) व्यवस्था के अंतर्गत इस गिरजाघर की देखरेख यूनानी ऑर्थोडॉक्स, रोमन कैथोलिक (फ़्रांसिस्कन) और आर्मेनियाई प्रेरितिक कलीसियाएँ मिलकर करती हैं, जबकि कॉप्टिक, इथियोपियाई और सीरियाई ऑर्थोडॉक्स समुदायों के भी यहाँ अपने चैपल हैं। इसके द्वार हर सुबह उन मुस्लिम परिवारों द्वारा खोले जाते हैं जो सदियों से इसकी चाबियाँ सँभालते आए हैं।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
