INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', '593f2031-2c23-4d15-86c5-7487a8296b4f', 'content', 'hi', 'संरचनात्मक मूल्यांकन का चरण सफलतापूर्वक पूरा हो गया है। इंजीनियरों ने उन मुख्य हिस्सों की पहचान कर ली है जिन पर ध्यान देने की आवश्यकता है।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
