INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', 'ee7631c8-fb98-4e45-b8ea-9fa78251cd23', 'content', 'hi', 'हमने उच्च-रिज़ॉल्यूशन फ़ोटोग्राफ़ी और 3D स्कैन के माध्यम से अपने पहले 50 विरासत स्थलों का सफलतापूर्वक दस्तावेज़ीकरण कर लिया है।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', 'ee7631c8-fb98-4e45-b8ea-9fa78251cd23', 'title', 'hi', 'पहले 50 स्थलों का दस्तावेज़ीकरण पूरा', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'hi', 'जीर्णोद्धार', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'hi', 'यह परियोजना महागिरजाघर के जीर्णोद्धार की सबसे ज़रूरी आवश्यकताओं पर केंद्रित है, जिनमें संरचनात्मक मरम्मत, अग्रभाग की सफ़ाई और मूल वास्तुशिल्पीय तत्वों का संरक्षण शामिल है। यह कार्य सुनिश्चित करेगा कि भवन आने वाली पीढ़ियों के लिए सुरक्षित और सुलभ बना रहे।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'hi', 'घोषणा के महागिरजाघर के मुख्य मध्यभाग और अग्रभाग का जीर्णोद्धार।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
