INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'hi', 'दस्तावेज़ीकरण', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'hi', 'इस्राएल और आसपास के क्षेत्रों में मसीही विरासत स्थलों, प्राचीन वस्तुओं और पांडुलिपियों की तस्वीरें लेने, उन्हें स्कैन करने और उनका दस्तावेज़ीकरण करने की एक व्यापक पहल। यह डिजिटल अभिलेखागार अमूल्य ऐतिहासिक अभिलेखों को शोधकर्ताओं और आने वाली पीढ़ियों के लिए सुरक्षित रखेगा।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'hi', 'पूरी पवित्र भूमि में फैले मसीही विरासत स्थलों का डिजिटल दस्तावेज़ीकरण।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'hi', 'पवित्र भूमि की विरासत का दस्तावेज़ीकरण', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'hr', 'Bazilika Navještenja katolička je crkva u Nazaretu, u Izraelu. Jedna je od najvećih crkava na Bliskom istoku i obilježava mjesto koje prema predaji označava gdje je arkanđeo Gabrijel navijestio Mariji da će roditi Isusa.', 'Današnja bazilika sagrađena je 1969. godine prema projektu talijanskog arhitekta Giovannija Muzija. Uzdiže se nad ruševinama ranijih bizantskih i križarskih crkava. Mjesto je odredište kršćanskih hodočašća od davnina.', 'Crkva služi mjesnoj katoličkoj zajednici u Nazaretu i prima hodočasnike iz cijeloga svijeta. Mise se redovito služe na više jezika.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'hr', 'Bazilika Rođenja Isusova u Betlehemu uzdiže se nad špiljom koju kršćanska predaja od 2. stoljeća štuje kao mjesto Isusova rođenja. Jedna je od najstarijih neprekidno korištenih crkava na svijetu i mjesto svjetske baštine UNESCO-a.', 'Prvu je baziliku dao podići car Konstantin s majkom Helenom oko 327. godine. Nakon što je oštećena u 6. stoljeću, car Justinijan obnovio ju je u većem opsegu i velik dio današnje crkve potječe iz te obnove. Unutra su i danas sačuvani mozaici i oslikani stupovi iz križarskoga doba.', 'Crkvu dijele grčka pravoslavna, rimokatolička (franjevačka) i armenska apostolska zajednica prema povijesnom statusu quo. Mjesne kršćanske obitelji iz Betlehema mole se ovdje zajedno s hodočasnicima iz cijeloga svijeta, osobito o Božiću.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'hr', 'Bazilika Svetoga groba u Starome gradu Jeruzalema sadrži dva najsvetija mjesta kršćanstva: Golgotu, gdje je Isus raspet, i grob u kojem je prema predaji pokopan i uskrsnuo.', 'Car Konstantin ovdje je u 4. stoljeću sagradio prvu crkvu; posvećena je 335. godine. Srušena je 1009. i obnovljena u 11. stoljeću, a križari su joj u 12. stoljeću dali velik dio današnjega izgleda. Edikula nad grobom obnovljena je 2016. – 2017. godine.', 'Skrb o crkvi dijele grčka pravoslavna, rimokatolička (franjevačka) i armenska apostolska crkva, dok koptska, etiopska i sirijska pravoslavna zajednica također imaju svoje kapele, prema statusu quo iz 1852. godine. Njezina vrata svakoga jutra otvaraju muslimanske obitelji koje stoljećima čuvaju ključeve.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
