INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'hr', 'Obnova', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'hr', 'Ovaj projekt usmjeren je na ključne potrebe obnove bazilike, uključujući konstrukcijske popravke, čišćenje pročelja i očuvanje izvornih arhitektonskih elemenata. Radovi će osigurati da građevina ostane sigurna i pristupačna za buduće naraštaje.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'hr', 'Obnova glavne lađe i pročelja Bazilike Navještenja.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'hr', 'Obnova bazilike — 1. faza', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'hr', 'Dokumentiranje', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'hr', 'Sveobuhvatna inicijativa za fotografiranje, skeniranje i dokumentiranje mjesta kršćanske baštine, artefakata i rukopisa diljem Izraela i susjednih regija. Ovaj digitalni arhiv sačuvat će neprocjenjive povijesne zapise za istraživače i buduće naraštaje.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'hr', 'Digitalno dokumentiranje mjesta kršćanske baštine diljem Svete zemlje.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'hr', 'Dokumentiranje baštine Svete zemlje', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'hu', 'Az Angyali üdvözlet-bazilika egy katolikus templom az izraeli Názáretben. A Közel-Kelet egyik legnagyobb temploma, és azt a hagyomány szerinti helyet jelöli, ahol Gábriel arkangyal hírül adta Máriának, hogy Jézust fogja szülni.', 'A jelenlegi bazilikát 1969-ben építették, Giovanni Muzio olasz építész tervei alapján. Korábbi bizánci és keresztes kori templomok romjai fölött áll. A helyszín az ókor óta a keresztény zarándoklat célpontja.', 'A templom a názáreti helyi katolikus közösséget szolgálja, és a világ minden tájáról érkező zarándokokat fogad. Rendszeresen tartanak miséket több nyelven.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'hu', 'A betlehemi Születés temploma azon barlang fölött áll, amelyet a keresztény hagyomány a 2. század óta Jézus születési helyeként tisztel. A világ egyik legrégebbi, folyamatosan használt temploma, és az UNESCO világörökség része.', 'Az első bazilikát Konstantin császár és édesanyja, Ilona építtette 327 körül. Miután a 6. században megsérült, Justinianus császár nagyobb léptékben újjáépíttette, és a mai templom nagy része ebből az újjáépítésből származik. A keresztes korból származó mozaikok és festett oszlopok ma is fennmaradtak a belsejében.', 'A templomon a görögkeleti, a római katolikus (ferences) és az örmény apostoli közösség osztozik a történelmi status quo megállapodás keretében. Betlehem helyi keresztény családjai a világ minden tájáról érkező zarándokokkal együtt imádkoznak itt, különösen karácsonykor.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'hu', 'A jeruzsálemi óvárosban található Szent Sír-templom a kereszténység két legszentebb helyét foglalja magában: a Golgotát, ahol Jézust keresztre feszítették, és a sírt, amelybe a hagyomány szerint eltemették, és amelyből feltámadt.', 'Konstantin császár a 4. században itt építtette az első templomot; 335-ben szentelték fel. 1009-ben elpusztult, a 11. században újjáépítették, a keresztesek pedig a 12. században nagyrészt mai formáját adták neki. A sír fölötti Ediculát 2016–2017-ben állították helyre.', 'A templom gondozásán a görögkeleti, a római katolikus (ferences) és az örmény apostoli egyház osztozik, míg a kopt, az etióp és a szír ortodox közösségek szintén rendelkeznek kápolnákkal, az 1852-es status quo szerint. Ajtajait minden reggel muszlim családok nyitják ki, akik évszázadok óta őrzik a kulcsokat.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
