INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'hu', 'Felújítás', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'hu', 'Ez a projekt a bazilika legégetőbb felújítási igényeire összpontosít, beleértve a szerkezeti javításokat, a homlokzat tisztítását és az eredeti építészeti elemek megőrzését. A munkálatok biztosítják, hogy az épület biztonságos és megközelíthető maradjon a jövő nemzedékei számára.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'hu', 'Az Angyali üdvözlet-bazilika főhajójának és homlokzatának felújítása.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'hu', 'A bazilika felújítása – 1. szakasz', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'hu', 'Dokumentáció', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'hu', 'Átfogó kezdeményezés a keresztény örökségi helyszínek, műtárgyak és kéziratok fényképezésére, szkennelésére és dokumentálására Izraelben és a környező régiókban. Ez a digitális archívum felbecsülhetetlen értékű történelmi feljegyzéseket őriz meg a kutatók és a jövő nemzedékei számára.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'hu', 'A keresztény örökségi helyszínek digitális dokumentálása a Szentföld egész területén.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'hu', 'A Szentföld örökségének dokumentálása', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'hy', 'Ավետման բազիլիկը կաթոլիկ եկեղեցի է Իսրայելի Նազարեթ քաղաքում։ Այն Մերձավոր Արևելքի ամենամեծ եկեղեցիներից մեկն է և կանգնած է այն վայրում, որտեղ, ըստ ավանդության, Գաբրիել հրեշտակապետը Կույս Մարիամին ավետեց, որ նա պիտի ծնի Հիսուսին։', 'Ներկայիս բազիլիկը կառուցվել է 1969 թվականին՝ իտալացի ճարտարապետ Ջովաննի Մուցիոյի նախագծով։ Այն վեր է խոյանում բյուզանդական և խաչակրաց ժամանակաշրջանների ավելի վաղ եկեղեցիների ավերակների վրա։ Հնագույն ժամանակներից ի վեր այս վայրը գրավում է քրիստոնյա ուխտավորներին։', 'Եկեղեցին ծառայում է Նազարեթի տեղի կաթոլիկ համայնքին և հյուրընկալում է աշխարհի տարբեր ծայրերից եկած ուխտավորներին։ Պատարագները կանոնավոր կերպով մատուցվում են տարբեր լեզուներով։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'hy', 'Բեթղեհեմի Սուրբ Ծննդյան տաճարը կանգնած է այն քարայրի վրա, որը քրիստոնեական ավանդությունը II դարից ի վեր մեծարում է որպես Հիսուսի ծննդավայր։ Այն աշխարհի ամենահին անընդմեջ գործող եկեղեցիներից մեկն է և ընդգրկված է ՅՈՒՆԵՍԿՕ-ի Համաշխարհային ժառանգության ցանկում։', 'Առաջին բազիլիկը կառուցվել է մ.թ. մոտ 327 թվականին՝ Կոստանդիանոս կայսեր և նրա մոր՝ Հեղինեի հրամանով։ VI դարում վնասվելուց հետո Հուստինիանոս կայսրն այն վերակառուցեց ավելի մեծ չափերով, և ներկայիս տաճարի զգալի մասը հենց այդ վերակառուցման ժամանակներից է։ Ներսում մինչ օրս պահպանվել են խաչակիրների դարաշրջանի խճանկարներ և նկարազարդ սյուներ։', 'Համաձայն պատմական Ստատուս քվոյի՝ տաճարը համատեղ տնօրինում են հույն ուղղափառ, հռոմեական կաթոլիկ (ֆրանցիսկյաններ) և հայ առաքելական համայնքները։ Բեթղեհեմի տեղացի քրիստոնյա ընտանիքներն այստեղ աղոթում են աշխարհի տարբեր ծայրերից եկած ուխտավորների հետ, հատկապես Սուրբ Ծննդյան տոներին։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'hy', 'Երուսաղեմի Հին քաղաքում գտնվող Սուրբ Հարության տաճարն իր մեջ ներառում է քրիստոնեության երկու մեծագույն սրբավայրերը՝ Գողգոթան, որտեղ խաչվեց Հիսուսը, և Սուրբ Գերեզմանը, որտեղ, ըստ ավանդության, Նա թաղվեց և հարություն առավ։', 'Կոստանդիանոս կայսրն այստեղ առաջին եկեղեցին կառուցեց IV դարում, և այն օծվեց մ.թ. 335 թվականին։ 1009 թվականին տաճարն ավերվեց, XI դարում վերակառուցվեց, իսկ XII դարում խաչակիրներն էականորեն ձևավորեցին նրա ներկայիս տեսքը։ Սուրբ Գերեզմանի վրա կառուցված մատուռը վերականգնվեց 2016–2017 թվականներին։', 'Տաճարի խնամքը համատեղ իրականացնում են Հույն ուղղափառ, Հռոմեական կաթոլիկ (ֆրանցիսկյաններ) և Հայ առաքելական եկեղեցիները, իսկ իրենց մատուռներն ունեն նաև ղպտի, եթովպական և ասորի ուղղափառ համայնքները։ Այս կարգը սահմանված է 1852 թվականի Ստատուս քվոյով։ Տաճարի դռներն ամեն առավոտ բացում են մահմեդական ընտանիքները, որոնք դարեր շարունակ պահում են դրա բանալիները։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
