INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'ba05a1f8-57a8-428d-955b-849cafe8e2d7', 'content', 'hy', 'Հրավիրում ենք Ձեզ Սուրբ Ծննդյան հատուկ պատարագներին և տոնական միջոցառումներին։ Ժամանակացույցը հասանելի է մեր կայքում։', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
