INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'id', 'Proyek ini berfokus pada kebutuhan restorasi penting basilika, termasuk perbaikan struktural, pembersihan fasad, dan pelestarian elemen arsitektur asli. Pekerjaan ini akan memastikan bangunan tetap aman dan dapat diakses untuk generasi mendatang.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'id', 'Restorasi nave utama dan fasad Basilika Kabar Sukacita.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
