INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'it', 'Restauro', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'it', 'Questo progetto si concentra sulle esigenze fondamentali di restauro della basilica, tra cui riparazioni strutturali, pulizia della facciata e conservazione degli elementi architettonici originali. I lavori garantiranno che l''edificio rimanga sicuro e accessibile per le generazioni future.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'it', 'Restauro della navata principale e della facciata della Basilica dell''Annunciazione.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'it', 'Restauro della basilica - Fase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'it', 'Documentazione', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'it', 'Un''iniziativa completa per fotografare, scansionare e documentare siti, manufatti e manoscritti del patrimonio cristiano in Israele e nelle regioni circostanti. Questo archivio digitale preserverà documenti storici inestimabili per i ricercatori e per le generazioni future.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'it', 'Documentazione digitale dei siti del patrimonio cristiano in tutta la Terra Santa.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'it', 'Documentazione del patrimonio di Terra Santa', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ja', '受胎告知教会は、イスラエルのナザレにあるカトリックの教会です。中東最大級の教会の一つで、大天使ガブリエルがマリアに、イエスを身ごもることを告げたと伝えられる場所に建っています。', '現在の聖堂は、イタリアの建築家ジョヴァンニ・ムツィオの設計により1969年に建てられました。ビザンツ時代と十字軍時代の教会の遺構の上に建っており、この地は古くからキリスト教の巡礼地となってきました。', 'この教会はナザレの地元カトリック共同体の拠り所であると同時に、世界中から訪れる巡礼者を迎え入れています。ミサは定期的に複数の言語で捧げられています。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ja', 'ベツレヘムの聖誕教会は、2世紀以来キリスト教の伝承がイエス誕生の地として崇敬してきた洞窟の上に建っています。現在まで途切れることなく使われ続けている教会としては世界最古級のものの一つであり、ユネスコの世界遺産にも登録されています。', '最初の聖堂は、西暦327年ごろ、コンスタンティヌス帝とその母ヘレナの命によって建てられました。6世紀に損傷を受けた後、ユスティニアヌス帝がより大規模に再建し、現在の教会の大部分はこの再建時のものです。内部には十字軍時代のモザイクや彩色された円柱が今も残っています。', 'この教会は、歴史的な「ステータス・クオ（現状維持協定）」のもと、ギリシャ正教会、ローマ・カトリック教会（フランシスコ会）、アルメニア使徒教会の三つの共同体によって共有されています。ベツレヘムの地元のキリスト教徒の家族が世界各地からの巡礼者とともにここで祈りを捧げており、特にクリスマスの時期には多くの人々が集います。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ja', 'エルサレム旧市街にある聖墳墓教会には、キリスト教で最も神聖な二つの場所があります。伝承によれば、イエスが十字架にかけられたゴルゴタと、イエスが葬られ、そして復活された墓です。', '4世紀、コンスタンティヌス帝がこの地に最初の教会を建て、西暦335年に献堂されました。1009年に破壊された後、11世紀に再建され、12世紀には十字軍によって現在の姿の多くが形づくられました。墓を覆う小聖堂（エディクラ）は2016年から2017年にかけて修復されました。', '1852年のステータス・クオのもと、教会の管理はギリシャ正教会、ローマ・カトリック教会（フランシスコ会）、アルメニア使徒教会が共同で担っており、コプト正教会、エチオピア正教会、シリア正教会もそれぞれ礼拝堂を持っています。教会の扉は毎朝、何世紀にもわたって鍵を守り続けてきたイスラム教徒の家族によって開けられます。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
