INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ja', 'イスラエルとその周辺地域にあるキリスト教の遺産、遺物、写本を撮影・スキャンし、記録する包括的な取り組みです。このデジタルアーカイブは、かけがえのない歴史的記録を研究者と将来の世代のために保存します。', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
