INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', 'ee7631c8-fb98-4e45-b8ea-9fa78251cd23', 'content', 'ka', 'ჩვენ წარმატებით დავასრულეთ მემკვიდრეობის პირველი 50 ძეგლის დოკუმენტირება მაღალი გარჩევადობის ფოტოებითა და 3D სკანირებით.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
