INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'ka', 'პროექტი მიზნად ისახავს ბაზილიკის გადაუდებელი სარესტავრაციო საჭიროებების დაკმაყოფილებას, მათ შორის კონსტრუქციების შეკეთებას, ფასადის წმენდასა და ორიგინალური არქიტექტურული ელემენტების შენარჩუნებას. სამუშაოები უზრუნველყოფს, რომ შენობა მომავალი თაობებისთვის უსაფრთხო და ხელმისაწვდომი დარჩეს.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'ka', 'ხარების ბაზილიკის მთავარი ნავისა და ფასადის რესტავრაცია.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
