INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'ko', '이 프로젝트는 구조 보수, 정면 외벽 세척, 원형 건축 요소 보존 등 대성당의 핵심적인 복원 작업에 중점을 둡니다. 이를 통해 건물이 앞으로도 안전하고 접근 가능한 상태를 유지하도록 할 것입니다.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'ko', '주님 탄생 예고 대성당의 본당과 정면 외벽 복원.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
