INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ml', 'മംഗളവാർത്ത ബസിലിക്ക ഇസ്രായേലിലെ നസ്രത്തിലുള്ള ഒരു കത്തോലിക്കാ ദേവാലയമാണ്. മധ്യപൂർവേഷ്യയിലെ ഏറ്റവും വലിയ ദേവാലയങ്ങളിലൊന്നായ ഇത്, യേശുവിനെ പ്രസവിക്കുമെന്ന് ഗബ്രിയേൽ പ്രധാനദൂതൻ മറിയത്തോട് അറിയിച്ചതായി പാരമ്പര്യം കരുതുന്ന സ്ഥലത്തെ അടയാളപ്പെടുത്തുന്നു.', 'ഇപ്പോഴത്തെ ബസിലിക്ക 1969-ൽ ഇറ്റാലിയൻ വാസ്തുശില്പി ജോവാന്നി മുസിയോ രൂപകൽപന ചെയ്ത് നിർമ്മിച്ചതാണ്. മുൻകാല ബൈസന്റൈൻ, കുരിശുയുദ്ധകാല ദേവാലയങ്ങളുടെ അവശിഷ്ടങ്ങൾക്കു മുകളിലാണ് ഇത് നിലകൊള്ളുന്നത്. പുരാതനകാലം മുതൽ ഈ സ്ഥലം ക്രൈസ്തവ തീർത്ഥാടന കേന്ദ്രമാണ്.', 'ഈ ദേവാലയം നസ്രത്തിലെ പ്രാദേശിക കത്തോലിക്കാ സമൂഹത്തെ സേവിക്കുകയും ലോകമെമ്പാടുമുള്ള തീർത്ഥാടകരെ സ്വാഗതം ചെയ്യുകയും ചെയ്യുന്നു. പല ഭാഷകളിൽ ക്രമമായി വിശുദ്ധ കുർബാന അർപ്പിക്കുന്നു.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ml', 'ബെത്‌ലഹേമിലെ ജനന ദേവാലയം, രണ്ടാം നൂറ്റാണ്ട് മുതൽ യേശുവിന്റെ ജന്മസ്ഥലമായി ക്രൈസ്തവ പാരമ്പര്യം ആദരിച്ചുപോരുന്ന ഗുഹയ്ക്കു മുകളിലാണ് നിലകൊള്ളുന്നത്. ലോകത്തിൽ തുടർച്ചയായി ഉപയോഗിക്കപ്പെടുന്ന ഏറ്റവും പുരാതനമായ ദേവാലയങ്ങളിലൊന്നും യുനെസ്കോ ലോക പൈതൃക കേന്ദ്രവുമാണ് ഇത്.', 'ആദ്യത്തെ ബസിലിക്ക ഏകദേശം എഡി 327-ൽ കോൺസ്റ്റന്റൈൻ ചക്രവർത്തിയും അമ്മ ഹെലേനയും ചേർന്ന് നിർമ്മിച്ചു. ആറാം നൂറ്റാണ്ടിൽ കേടുപാടു സംഭവിച്ചശേഷം ജസ്റ്റീനിയൻ ചക്രവർത്തി അതിനെ കൂടുതൽ വലുതായി പുനർനിർമ്മിച്ചു; ഇന്നത്തെ ദേവാലയത്തിന്റെ ഭൂരിഭാഗവും ആ പുനർനിർമ്മാണകാലത്തേതാണ്. കുരിശുയുദ്ധകാലത്തെ മൊസൈക്കുകളും ചിത്രാങ്കിത തൂണുകളും ഇന്നും അകത്ത് അവശേഷിക്കുന്നു.', 'ചരിത്രപ്രധാനമായ സ്റ്റാറ്റസ് ക്വോ ക്രമീകരണപ്രകാരം ഗ്രീക്ക് ഓർത്തഡോക്സ്, റോമൻ കത്തോലിക്ക (ഫ്രാൻസിസ്കൻ), അർമേനിയൻ അപ്പസ്തോലിക സമൂഹങ്ങൾ ഈ ദേവാലയം പങ്കിടുന്നു. ബെത്‌ലഹേമിലെ പ്രാദേശിക ക്രൈസ്തവ കുടുംബങ്ങൾ, വിശേഷിച്ച് ക്രിസ്മസ് കാലത്ത്, ലോകമെമ്പാടുമുള്ള തീർത്ഥാടകർക്കൊപ്പം ഇവിടെ ആരാധിക്കുന്നു.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ml', 'ജറുസലേമിലെ പഴയ നഗരത്തിലുള്ള വിശുദ്ധ കബറിടദേവാലയത്തിൽ ക്രിസ്തുമതത്തിലെ ഏറ്റവും വിശുദ്ധമായ രണ്ട് സ്ഥലങ്ങളുണ്ട്: യേശു ക്രൂശിക്കപ്പെട്ട ഗാഗുൽത്തയും, പാരമ്പര്യപ്രകാരം അവിടുന്ന് അടക്കപ്പെടുകയും ഉയിർത്തെഴുന്നേൽക്കുകയും ചെയ്ത കബറിടവും.', 'കോൺസ്റ്റന്റൈൻ ചക്രവർത്തി നാലാം നൂറ്റാണ്ടിൽ ഇവിടെ ആദ്യത്തെ ദേവാലയം നിർമ്മിച്ചു; എഡി 335-ൽ അത് പ്രതിഷ്ഠിക്കപ്പെട്ടു. 1009-ൽ ഇത് നശിപ്പിക്കപ്പെടുകയും പതിനൊന്നാം നൂറ്റാണ്ടിൽ പുനർനിർമ്മിക്കപ്പെടുകയും ചെയ്തു; പന്ത്രണ്ടാം നൂറ്റാണ്ടിൽ കുരിശുയുദ്ധക്കാർ ഇന്നത്തെ രൂപത്തിന്റെ ഭൂരിഭാഗവും ഇതിന് നൽകി. കബറിടത്തിനു മുകളിലുള്ള എദിക്യൂൾ (ചെറു പുണ്യമന്ദിരം) 2016–2017-ൽ പുനരുദ്ധരിച്ചു.', '1852-ലെ സ്റ്റാറ്റസ് ക്വോ പ്രകാരം ഗ്രീക്ക് ഓർത്തഡോക്സ്, റോമൻ കത്തോലിക്ക (ഫ്രാൻസിസ്കൻ), അർമേനിയൻ അപ്പസ്തോലിക സഭകൾ ചേർന്നാണ് ഈ ദേവാലയത്തിന്റെ പരിപാലനം; കോപ്റ്റിക്, എത്യോപ്യൻ, സുറിയാനി ഓർത്തഡോക്സ് സമൂഹങ്ങൾക്കും ഇവിടെ ചാപ്പലുകളുണ്ട്. നൂറ്റാണ്ടുകളായി താക്കോലുകൾ സൂക്ഷിച്ചുപോരുന്ന മുസ്ലിം കുടുംബങ്ങളാണ് ഓരോ പ്രഭാതത്തിലും ഇതിന്റെ വാതിലുകൾ തുറക്കുന്നത്.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
