INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'ba05a1f8-57a8-428d-955b-849cafe8e2d7', 'content', 'ml', 'പ്രത്യേക ക്രിസ്മസ് കുർബാനകൾക്കും ആഘോഷങ്ങൾക്കും ഞങ്ങളോടൊപ്പം ചേരുക. സമയക്രമം ഞങ്ങളുടെ വെബ്‌സൈറ്റിൽ ലഭ്യമാണ്.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
