INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', '593f2031-2c23-4d15-86c5-7487a8296b4f', 'content', 'ml', 'ഘടനാപരമായ വിലയിരുത്തൽ ഘട്ടം വിജയകരമായി പൂർത്തിയായി. ശ്രദ്ധ ആവശ്യമുള്ള പ്രധാന മേഖലകൾ എൻജിനിയർമാർ കണ്ടെത്തിയിട്ടുണ്ട്.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
