INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', 'ee7631c8-fb98-4e45-b8ea-9fa78251cd23', 'content', 'ml', 'ഉയർന്ന റെസല്യൂഷനുള്ള ഫോട്ടോഗ്രഫിയും 3D സ്കാനുകളും ഉപയോഗിച്ച് ഞങ്ങളുടെ ആദ്യ 50 പൈതൃക കേന്ദ്രങ്ങൾ വിജയകരമായി രേഖപ്പെടുത്തി.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
