INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'ml', 'ഘടനാപരമായ അറ്റകുറ്റപ്പണികൾ, മുൻഭാഗം വൃത്തിയാക്കൽ, യഥാർത്ഥ വാസ്തുവിദ്യാ ഘടകങ്ങളുടെ സംരക്ഷണം എന്നിവയുൾപ്പെടെ ബസിലിക്കയുടെ അത്യാവശ്യ പുനരുദ്ധാരണ ആവശ്യങ്ങളിലാണ് ഈ പദ്ധതി ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നത്. വരുംതലമുറകൾക്കായി കെട്ടിടം സുരക്ഷിതവും പ്രാപ്യവുമായി തുടരുന്നുവെന്ന് ഈ പ്രവർത്തനം ഉറപ്പാക്കും.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'ml', 'മംഗളവാർത്ത ബസിലിക്കയുടെ പ്രധാന നടുത്തളത്തിന്റെയും മുൻഭാഗത്തിന്റെയും പുനരുദ്ധാരണം.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'ml', 'ബസിലിക്ക പുനരുദ്ധാരണം - ഒന്നാം ഘട്ടം', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
