INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ml', 'ഇസ്രായേലിലും സമീപ പ്രദേശങ്ങളിലുമുള്ള ക്രൈസ്തവ പൈതൃക കേന്ദ്രങ്ങൾ, പുരാവസ്തുക്കൾ, കൈയെഴുത്തുപ്രതികൾ എന്നിവ ഫോട്ടോയെടുക്കാനും സ്കാൻ ചെയ്യാനും രേഖപ്പെടുത്താനുമുള്ള സമഗ്രമായ ഒരു സംരംഭം. ഈ ഡിജിറ്റൽ ശേഖരം ഗവേഷകർക്കും വരുംതലമുറകൾക്കുമായി വിലമതിക്കാനാവാത്ത ചരിത്രരേഖകൾ കാത്തുസൂക്ഷിക്കും.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'ml', 'വിശുദ്ധനാട്ടിലുടനീളമുള്ള ക്രൈസ്തവ പൈതൃക കേന്ദ്രങ്ങളുടെ ഡിജിറ്റൽ രേഖപ്പെടുത്തൽ.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'ml', 'വിശുദ്ധനാട് പൈതൃക രേഖപ്പെടുത്തൽ', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'nl', 'De Basiliek van de Aankondiging is een katholieke kerk in Nazareth, Israël. Het is een van de grootste kerken in het Midden-Oosten en markeert de traditionele plaats waar de aartsengel Gabriël aan Maria verkondigde dat zij Jezus zou baren.', 'De huidige basiliek werd in 1969 gebouwd, ontworpen door de Italiaanse architect Giovanni Muzio. Ze staat boven de ruïnes van eerdere Byzantijnse en kruisvaarderskerken. De plaats is sinds de oudheid een oord van christelijke bedevaart.', 'De kerk dient de plaatselijke katholieke gemeenschap in Nazareth en verwelkomt pelgrims van over de hele wereld. Er worden regelmatig missen in meerdere talen gehouden.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'nl', 'De Geboortekerk in Bethlehem staat boven de grot die de christelijke traditie sinds de 2e eeuw vereert als de geboorteplaats van Jezus. Het is een van de oudste onafgebroken gebruikte kerken ter wereld en een werelderfgoed van UNESCO.', 'De eerste basiliek werd rond 327 na Chr. in opdracht gegeven door keizer Constantijn en zijn moeder Helena. Nadat ze in de 6e eeuw beschadigd raakte, liet keizer Justinianus haar op grotere schaal herbouwen, en een groot deel van de huidige kerk stamt uit die herbouw. Mozaïeken en beschilderde zuilen uit de kruisvaarderstijd zijn binnen nog bewaard gebleven.', 'De kerk wordt gedeeld door de Grieks-orthodoxe, de rooms-katholieke (franciscaanse) en de Armeens-apostolische gemeenschap onder de historische status-quoregeling. Plaatselijke christelijke families uit Bethlehem bidden hier samen met pelgrims van over de hele wereld, vooral met Kerstmis.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'nl', 'De Heilig Grafkerk in de oude stad van Jeruzalem bevat de twee heiligste plaatsen van het christendom: Golgotha, waar Jezus werd gekruisigd, en het graf waar hij volgens de traditie werd begraven en weer opstond.', 'Keizer Constantijn liet hier in de 4e eeuw de eerste kerk bouwen; ze werd in 335 na Chr. ingewijd. Ze werd in 1009 verwoest en in de 11e eeuw herbouwd, en de kruisvaarders gaven haar in de 12e eeuw grotendeels haar huidige vorm. De Edicula boven het graf werd in 2016–2017 gerestaureerd.', 'De zorg voor de kerk wordt gedeeld door de Grieks-orthodoxe, de rooms-katholieke (franciscaanse) en de Armeens-apostolische kerk, terwijl de Koptische, Ethiopische en Syrisch-orthodoxe gemeenschappen ook kapellen bezitten, onder de status quo van 1852. De deuren worden elke ochtend geopend door moslimfamilies die de sleutels al eeuwenlang bewaren.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
