INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', '593f2031-2c23-4d15-86c5-7487a8296b4f', 'content', 'nl', 'De fase van de structurele beoordeling is succesvol afgerond. Ingenieurs hebben de belangrijkste aandachtsgebieden vastgesteld.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
