INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'nl', 'Restauratie', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'nl', 'Dit project richt zich op de dringende restauratiebehoeften van de basiliek, waaronder structurele reparaties, reiniging van de gevel en behoud van originele architectonische elementen. De werkzaamheden zorgen ervoor dat het gebouw veilig en toegankelijk blijft voor toekomstige generaties.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'nl', 'Restauratie van het middenschip en de gevel van de Basiliek van de Aankondiging.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'nl', 'Restauratie van de basiliek – fase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'nl', 'Documentatie', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'nl', 'Een uitgebreid initiatief om christelijke erfgoedlocaties, artefacten en manuscripten in Israël en de omliggende regio’s te fotograferen, te scannen en te documenteren. Dit digitale archief bewaart onschatbare historische gegevens voor onderzoekers en toekomstige generaties.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'nl', 'Digitale documentatie van christelijke erfgoedlocaties in het hele Heilige Land.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'nl', 'Documentatie van het erfgoed van het Heilige Land', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'pl', 'Bazylika Zwiastowania to kościół katolicki w Nazarecie, w Izraelu. Jest jednym z największych kościołów na Bliskim Wschodzie i wyznacza tradycyjne miejsce, w którym archanioł Gabriel zwiastował Maryi, że pocznie i porodzi Jezusa.', 'Obecna bazylika została zbudowana w 1969 roku według projektu włoskiego architekta Giovanniego Muzio. Wznosi się nad ruinami wcześniejszych kościołów bizantyjskich i krzyżowieckich. Miejsce to jest celem chrześcijańskich pielgrzymek od czasów starożytnych.', 'Kościół służy miejscowej wspólnocie katolickiej w Nazarecie i przyjmuje pielgrzymów z całego świata. Regularne msze odprawiane są w wielu językach.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'pl', 'Bazylika Narodzenia Pańskiego w Betlejem wznosi się nad grotą, którą tradycja chrześcijańska czci od II wieku jako miejsce narodzin Jezusa. Jest to jeden z najstarszych nieprzerwanie użytkowanych kościołów na świecie oraz obiekt z Listy Światowego Dziedzictwa UNESCO.', 'Pierwszą bazylikę wzniesiono z polecenia cesarza Konstantyna i jego matki Heleny około 327 roku n.e. Po zniszczeniach w VI wieku cesarz Justynian odbudował ją na większą skalę, a znaczna część dzisiejszego kościoła pochodzi z tej przebudowy. Wewnątrz zachowały się mozaiki i malowane kolumny z okresu wypraw krzyżowych.', 'Kościołem opiekują się wspólnie wspólnoty greckoprawosławna, rzymskokatolicka (franciszkańska) i ormiańsko-apostolska, zgodnie z historycznym porozumieniem status quo. Miejscowe chrześcijańskie rodziny z Betlejem modlą się tu wraz z pielgrzymami z całego świata, zwłaszcza w okresie Bożego Narodzenia.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'pl', 'Bazylika Grobu Świętego w Starym Mieście w Jerozolimie mieści dwa najświętsze miejsca chrześcijaństwa: Golgotę, gdzie ukrzyżowano Jezusa, oraz grób, w którym – według tradycji – został złożony i zmartwychwstał.', 'Cesarz Konstantyn wzniósł tu pierwszy kościół w IV wieku; został on poświęcony w 335 roku n.e. Zniszczony w 1009 roku, odbudowany w XI wieku, a krzyżowcy nadali mu w dużej mierze obecny kształt w XII wieku. Edikula nad grobem została odrestaurowana w latach 2016–2017.', 'Opiekę nad kościołem sprawują wspólnie Kościoły greckoprawosławny, rzymskokatolicki (franciszkański) i ormiańsko-apostolski, a wspólnoty koptyjska, etiopska i syryjska prawosławna posiadają tu również własne kaplice, zgodnie ze status quo z 1852 roku. Jego drzwi każdego ranka otwierają muzułmańskie rodziny, które od wieków strzegą kluczy.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
