INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'pl', 'Renowacja', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'pl', 'Ten projekt koncentruje się na najpilniejszych potrzebach renowacyjnych bazyliki, obejmujących naprawy konstrukcyjne, czyszczenie fasady oraz zachowanie oryginalnych elementów architektonicznych. Prace zapewnią, że budynek pozostanie bezpieczny i dostępny dla przyszłych pokoleń.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'pl', 'Renowacja głównej nawy i fasady Bazyliki Zwiastowania.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'pl', 'Renowacja bazyliki – etap 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'pl', 'Dokumentacja', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'pl', 'Kompleksowa inicjatywa mająca na celu fotografowanie, skanowanie i dokumentowanie miejsc, artefaktów i rękopisów chrześcijańskiego dziedzictwa w Izraelu i okolicznych regionach. To cyfrowe archiwum zachowa bezcenne zapisy historyczne dla badaczy i przyszłych pokoleń.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'pl', 'Cyfrowa dokumentacja miejsc chrześcijańskiego dziedzictwa w całej Ziemi Świętej.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'pl', 'Dokumentacja dziedzictwa Ziemi Świętej', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'pt', 'A Basílica da Anunciação é uma igreja católica em Nazaré, Israel. É uma das maiores igrejas do Oriente Médio e marca o local tradicional onde o Arcanjo Gabriel anunciou a Maria que ela geraria Jesus.', 'A basílica atual foi construída em 1969, com projeto do arquiteto italiano Giovanni Muzio. Ela se ergue sobre as ruínas de igrejas bizantinas e cruzadas anteriores. O local é um destino de peregrinação cristã desde a Antiguidade.', 'A igreja atende a comunidade católica local de Nazaré e recebe peregrinos de todo o mundo. Missas regulares são celebradas em vários idiomas.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'pt', 'A Basílica da Natividade, em Belém, ergue-se sobre a gruta que a tradição cristã venera desde o século II como o local de nascimento de Jesus. É uma das igrejas em uso contínuo mais antigas do mundo e Patrimônio Mundial da UNESCO.', 'A primeira basílica foi encomendada pelo imperador Constantino e por sua mãe, Helena, por volta do ano 327 d.C. Após ser danificada no século VI, o imperador Justiniano a reconstruiu em maior escala, e grande parte da igreja atual data dessa reconstrução. Mosaicos e colunas pintadas da era das Cruzadas ainda sobrevivem em seu interior.', 'A igreja é compartilhada pelas comunidades ortodoxa grega, católica romana (franciscana) e apostólica armênia sob o histórico acordo do Status Quo. Famílias cristãs locais de Belém oram ali ao lado de peregrinos de todo o mundo, especialmente no Natal.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'pt', 'A Igreja do Santo Sepulcro, na Cidade Velha de Jerusalém, abriga os dois lugares mais sagrados do cristianismo: o Gólgota, onde Jesus foi crucificado, e o túmulo onde, segundo a tradição, ele foi sepultado e ressuscitou.', 'O imperador Constantino construiu a primeira igreja neste local no século IV; ela foi consagrada em 335 d.C. Foi destruída em 1009 e reconstruída no século XI, e os cruzados lhe deram grande parte de sua forma atual no século XII. O Edículo sobre o túmulo foi restaurado entre 2016 e 2017.', 'O cuidado da igreja é compartilhado pelas igrejas ortodoxa grega, católica romana (franciscana) e apostólica armênia, enquanto as comunidades copta, etíope e siríaca ortodoxa também mantêm capelas próprias, conforme o Status Quo de 1852. Suas portas são abertas todas as manhãs por famílias muçulmanas que guardam as chaves há séculos.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
