INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'pt', 'Restauração', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'pt', 'Este projeto se concentra nas necessidades críticas de restauração da basílica, incluindo reparos estruturais, limpeza da fachada e preservação dos elementos arquitetônicos originais. O trabalho garantirá que o edifício permaneça seguro e acessível para as futuras gerações.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'pt', 'Restauração da nave principal e da fachada da Basílica da Anunciação.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'pt', 'Restauração da basílica - Fase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'pt', 'Documentação', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'pt', 'Uma iniciativa abrangente para fotografar, escanear e documentar sítios, artefatos e manuscritos do patrimônio cristão em Israel e nas regiões vizinhas. Este acervo digital preservará registros históricos inestimáveis para pesquisadores e para as futuras gerações.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'pt', 'Documentação digital de sítios do patrimônio cristão em toda a Terra Santa.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'pt', 'Documentação do patrimônio da Terra Santa', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ro', 'Bazilica Buneivestiri este o biserică catolică din Nazaret, Israel. Este una dintre cele mai mari biserici din Orientul Mijlociu și marchează locul tradițional unde Arhanghelul Gavriil i-a vestit Mariei că îl va naște pe Isus.', 'Actuala bazilică a fost construită în 1969, după planurile arhitectului italian Giovanni Muzio. Ea se înalță deasupra ruinelor unor biserici bizantine și cruciate mai vechi. Locul este un loc de pelerinaj creștin încă din antichitate.', 'Biserica deservește comunitatea catolică locală din Nazaret și primește pelerini din întreaga lume. Slujbele obișnuite se oficiază în mai multe limbi.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ro', 'Biserica Nașterii Domnului din Betleem se înalță deasupra grotei pe care tradiția creștină o cinstește încă din secolul al II-lea drept locul nașterii lui Isus. Este una dintre cele mai vechi biserici aflate în folosință neîntreruptă din lume și sit al Patrimoniului Mondial UNESCO.', 'Prima bazilică a fost ridicată din porunca împăratului Constantin și a mamei sale, Elena, în jurul anului 327 d.Hr. După ce a fost avariată în secolul al VI-lea, împăratul Justinian a reconstruit-o la o scară mai mare, iar o mare parte din biserica de astăzi datează din acea reconstrucție. Mozaicuri și coloane pictate din perioada cruciaților se păstrează și astăzi în interior.', 'Biserica este împărțită între comunitățile ortodoxă greacă, romano-catolică (franciscană) și apostolică armeană, în cadrul înțelegerii istorice de Status quo. Familiile creștine locale din Betleem se roagă aici alături de pelerini veniți din întreaga lume, mai ales de Crăciun.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ro', 'Biserica Sfântului Mormânt din Orașul Vechi al Ierusalimului cuprinde cele mai sfinte două locuri ale creștinătății: Golgota, unde Isus a fost răstignit, și mormântul în care, potrivit tradiției, a fost așezat și a înviat.', 'Împăratul Constantin a construit aici prima biserică în secolul al IV-lea; ea a fost sfințită în anul 335 d.Hr. A fost distrusă în anul 1009 și reconstruită în secolul al XI-lea, iar cruciații i-au dat forma actuală, în mare parte, în secolul al XII-lea. Edicula de deasupra mormântului a fost restaurată în perioada 2016–2017.', 'Îngrijirea bisericii este împărțită între Bisericile ortodoxă greacă, romano-catolică (franciscană) și apostolică armeană, comunitățile coptă, etiopiană și siriacă ortodoxă deținând, de asemenea, paraclise proprii, conform Status quo-ului din 1852. Ușile sale sunt deschise în fiecare dimineață de familii musulmane care păstrează cheile de secole.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
