INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'ro', 'Restaurare', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'ro', 'Acest proiect se concentrează pe nevoile critice de restaurare ale bazilicii, incluzând reparații structurale, curățarea fațadei și conservarea elementelor arhitecturale originale. Lucrările vor asigura că edificiul rămâne sigur și accesibil pentru generațiile viitoare.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'ro', 'Restaurarea navei principale și a fațadei Bazilicii Buneivestiri.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'ro', 'Restaurarea bazilicii – Faza 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'ro', 'Documentare', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ro', 'O inițiativă amplă de fotografiere, scanare și documentare a siturilor, artefactelor și manuscriselor de patrimoniu creștin din Israel și din regiunile învecinate. Această arhivă digitală va păstra înregistrări istorice neprețuite pentru cercetători și generațiile viitoare.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'ro', 'Documentare digitală a siturilor de patrimoniu creștin din întreaga Țară Sfântă.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'ro', 'Documentarea patrimoniului Țării Sfinte', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ru', 'Базилика Благовещения — католический храм в Назарете (Израиль). Это одна из крупнейших церквей на Ближнем Востоке. Она стоит на месте, где, по преданию, Архангел Гавриил возвестил Деве Марии, что она родит Иисуса.', 'Нынешняя базилика построена в 1969 году по проекту итальянского архитектора Джованни Муцио. Она возвышается над руинами более древних церквей византийской эпохи и эпохи крестовых походов. С древних времён это место привлекает христианских паломников.', 'Храм служит местной католической общине Назарета и принимает паломников со всего мира. Мессы регулярно совершаются на нескольких языках.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ru', 'Храм Рождества Христова в Вифлееме стоит над пещерой, которую христианская традиция со II века почитает как место рождения Иисуса. Это одна из древнейших непрерывно действующих церквей в мире и объект Всемирного наследия ЮНЕСКО.', 'Первая базилика была возведена около 327 года н. э. по повелению императора Константина и его матери Елены. После повреждений в VI веке император Юстиниан перестроил её в большем масштабе, и значительная часть нынешнего храма восходит к этой перестройке. Внутри до сих пор сохранились мозаики и расписные колонны эпохи крестоносцев.', 'Храм находится в совместном ведении трёх общин — греческой православной, римско-католической (францисканцы) и армянской апостольской — в соответствии с историческим статус-кво. Местные христианские семьи Вифлеема молятся здесь вместе с паломниками со всего мира, особенно на Рождество.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ru', 'Храм Гроба Господня в Старом городе Иерусалима объединяет две величайшие святыни христианства: Голгофу, где был распят Иисус, и Гроб Господень — место, где, по преданию, Он был погребён и воскрес.', 'Первый храм здесь построил император Константин в IV веке; он был освящён в 335 году н. э. В 1009 году храм был разрушен, в XI веке восстановлен, а в XII веке крестоносцы во многом придали ему нынешний облик. Кувуклия над Гробом Господним была отреставрирована в 2016–2017 годах.', 'Храм находится в совместном ведении трёх церквей — Греческой православной, Римско-католической (францисканцы) и Армянской апостольской; свои приделы есть также у православных общин коптов, эфиопов и сирийцев. Этот порядок закреплён статус-кво 1852 года. Каждое утро двери храма открывают мусульманские семьи, веками хранящие его ключи.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
