INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'ru', 'Реставрация', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'ru', 'Проект направлен на решение неотложных реставрационных задач базилики, включая ремонт конструкций, очистку фасада и сохранение подлинных архитектурных элементов. Работы обеспечат безопасность и доступность здания для будущих поколений.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'ru', 'Реставрация главного нефа и фасада Базилики Благовещения.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'ru', 'Реставрация базилики — этап 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'ru', 'Документирование', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ru', 'Масштабная инициатива по фотографированию, сканированию и документированию объектов христианского наследия, артефактов и рукописей в Израиле и соседних регионах. Этот цифровой архив сохранит бесценные исторические свидетельства для исследователей и будущих поколений.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'ru', 'Цифровое документирование объектов христианского наследия по всей Святой земле.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'ru', 'Документирование наследия Святой земли', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'sr', 'Базилика Благовести је католичка црква у Назарету, у Израелу. То је једна од највећих цркава на Блиском истоку и обележава место које по предању означава где је арханђео Гаврило објавио Марији да ће родити Исуса.', 'Данашња базилика саграђена је 1969. године, по пројекту италијанског архитекте Ђованија Муција. Уздиже се над рушевинама ранијих византијских и крсташких цркава. Ово место је од давнина одредиште хришћанских ходочасника.', 'Црква служи локалној католичкој заједници у Назарету и дочекује ходочаснике из целог света. Мисе се редовно служе на више језика.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'sr', 'Црква Рождења Христовог у Витлејему уздиже се над пећином коју хришћанска традиција од 2. века поштује као место рођења Исуса. То је једна од најстаријих непрекидно коришћених цркава на свету и место Светске баштине УНЕСКО-а.', 'Прву базилику подигли су око 327. године цар Константин и његова мајка Јелена. Пошто је оштећена у 6. веку, цар Јустинијан обновио ју је у већем обиму, а велики део данашње цркве потиче из те обнове. Унутра су и данас сачувани мозаици и осликани стубови из доба крсташа.', 'Црквом заједнички управљају грчка православна, римокатоличка (фрањевачка) и јерменска апостолска заједница, у складу са историјским статусом кво. Локалне хришћанске породице из Витлејема се овде моле заједно са ходочасницима из целог света, нарочито о Божићу.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'sr', 'Црква Светог гроба у Старом граду Јерусалима садржи две најсветије светиње хришћанства: Голготу, где је Исус разапет, и гроб у коме је, по предању, сахрањен и васкрсао.', 'Цар Константин је овде у 4. веку саградио прву цркву; освештана је 335. године. Порушена је 1009. и обновљена у 11. веку, а крсташи су јој у 12. веку дали највећи део данашњег изгледа. Едикула над гробом обновљена је 2016–2017. године.', 'О цркви заједнички брину грчка православна, римокатоличка (фрањевачка) и јерменска апостолска црква, док своје капеле имају и коптска, етиопска и сиријска православна заједница, у складу са статусом кво из 1852. године. Њена врата свако јутро отварају муслиманске породице које вековима чувају кључеве.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
