INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'sr', 'Обнова', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'sr', 'Овај пројекат усредсређен је на неопходне радове на обнови базилике, укључујући поправке конструкције, чишћење фасаде и очување изворних архитектонских елемената. Радови ће обезбедити да грађевина остане безбедна и приступачна за будуће нараштаје.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'sr', 'Обнова главне лађе и фасаде Базилике Благовести.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'sr', 'Обнова базилике — прва фаза', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'sr', 'Документовање', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'sr', 'Свеобухватна иницијатива за фотографисање, скенирање и документовање места хришћанског наслеђа, артефаката и рукописа широм Израела и суседних региона. Овај дигитални архив сачуваће непроцењиве историјске записе за истраживаче и будуће нараштаје.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'sr', 'Дигитално документовање места хришћанског наслеђа широм Свете земље.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'sr', 'Документовање наслеђа Свете земље', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'sv', 'Bebådelsebasilikan är en katolsk kyrka i Nasaret, Israel. Den är en av de största kyrkorna i Mellanöstern och markerar den traditionella platsen där ärkeängeln Gabriel förkunnade för Maria att hon skulle föda Jesus.', 'Den nuvarande basilikan byggdes 1969, ritad av den italienske arkitekten Giovanni Muzio. Den står över ruinerna av tidigare bysantinska kyrkor och korsfararkyrkor. Platsen har varit ett mål för kristen pilgrimsfärd sedan urminnes tider.', 'Kyrkan tjänar den lokala katolska gemenskapen i Nasaret och välkomnar pilgrimer från hela världen. Mässor hålls regelbundet på flera språk.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'sv', 'Födelsekyrkan i Betlehem står över den grotta som den kristna traditionen sedan 200-talet vördar som Jesu födelseplats. Den är en av världens äldsta kyrkor i oavbruten användning och ett Unesco-världsarv.', 'Den första basilikan uppfördes på uppdrag av kejsar Konstantin och hans mor Helena omkring år 327 e.Kr. Efter att den skadats på 500-talet lät kejsar Justinianus bygga om den i större skala, och en stor del av dagens kyrka härrör från den ombyggnaden. Mosaiker och målade pelare från korsfarartiden finns fortfarande bevarade inuti.', 'Kyrkan delas av den grekisk-ortodoxa, den romersk-katolska (franciskanska) och den armenisk-apostoliska gemenskapen enligt den historiska status quo-ordningen. Lokala kristna familjer i Betlehem ber här tillsammans med pilgrimer från hela världen, särskilt vid jul.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'sv', 'Den heliga gravens kyrka i Jerusalems gamla stad rymmer kristendomens två heligaste platser: Golgata, där Jesus korsfästes, och graven där han enligt traditionen begravdes och uppstod.', 'Kejsar Konstantin lät bygga den första kyrkan här på 300-talet; den invigdes år 335 e.Kr. Den förstördes 1009 och byggdes upp igen på 1000-talet, och korsfararna gav den till stor del dess nuvarande form på 1100-talet. Ädikulan över graven restaurerades 2016–2017.', 'Vården av kyrkan delas av den grekisk-ortodoxa, den romersk-katolska (franciskanska) och den armenisk-apostoliska kyrkan, medan de koptiska, etiopiska och syrisk-ortodoxa gemenskaperna också har kapell, enligt status quo från 1852. Dess dörrar öppnas varje morgon av muslimska familjer som har bevarat nycklarna i århundraden.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
