INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'sv', 'Restaurering', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'sv', 'Detta projekt fokuserar på basilikans mest akuta restaureringsbehov, inklusive strukturella reparationer, rengöring av fasaden och bevarande av ursprungliga arkitektoniska element. Arbetet säkerställer att byggnaden förblir säker och tillgänglig för kommande generationer.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'sv', 'Restaurering av mittskeppet och fasaden på Bebådelsebasilikan.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'sv', 'Restaurering av basilikan – fas 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'sv', 'Dokumentation', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'sv', 'Ett omfattande initiativ för att fotografera, skanna och dokumentera kristna kulturarvsplatser, artefakter och manuskript i Israel och de omgivande regionerna. Detta digitala arkiv bevarar ovärderliga historiska uppgifter för forskare och kommande generationer.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'sv', 'Digital dokumentation av kristna kulturarvsplatser i hela Heliga landet.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'sv', 'Dokumentation av Heliga landets arv', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'tr', 'Müjde Bazilikası, İsrail''in Nasıra kentinde bir Katolik kilisesidir. Orta Doğu''nun en büyük kiliselerinden biridir ve geleneğe göre Başmelek Cebrail''in Meryem''e İsa''yı doğuracağını müjdelediği yeri işaret eder.', 'Bugünkü bazilika, İtalyan mimar Giovanni Muzio''nun tasarımıyla 1969 yılında inşa edilmiştir. Daha önceki Bizans ve Haçlı dönemi kiliselerinin kalıntıları üzerinde yükselir. Bu mekân, kadim zamanlardan beri bir Hristiyan hac merkezidir.', 'Kilise, Nasıra''daki yerel Katolik topluluğa hizmet eder ve dünyanın dört bir yanından hacıları ağırlar. Ayinler düzenli olarak birçok dilde yapılır.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'tr', 'Beytüllahim''deki Doğuş Kilisesi, Hristiyan geleneğinin 2. yüzyıldan beri İsa''nın doğum yeri olarak andığı mağaranın üzerinde yükselir. Dünyada kesintisiz kullanılan en eski kiliselerden biri ve bir UNESCO Dünya Mirası alanıdır.', 'İlk bazilika, yaklaşık MS 327 yılında İmparator Konstantin ve annesi Helena tarafından yaptırılmıştır. 6. yüzyılda zarar gördükten sonra İmparator Justinianus onu daha büyük ölçekte yeniden inşa ettirmiş ve bugünkü kilisenin büyük bölümü bu yeniden inşadan kalmıştır. İçeride Haçlı dönemine ait mozaikler ve boyalı sütunlar hâlâ ayaktadır.', 'Kilise, tarihi Statüko düzenlemesi uyarınca Rum Ortodoks, Roma Katolik (Fransisken) ve Ermeni Apostolik topluluklarınca paylaşılır. Beytüllahim''in yerel Hristiyan aileleri, özellikle Noel''de dünyanın dört bir yanından gelen hacılarla birlikte burada ibadet eder.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'tr', 'Kudüs''ün Eski Şehri''ndeki Kutsal Kabir Kilisesi, Hristiyanlığın en kutsal iki yerini barındırır: İsa''nın çarmıha gerildiği Golgota ve geleneğe göre gömülüp yeniden dirildiği kabir.', 'İmparator Konstantin ilk kiliseyi burada 4. yüzyılda inşa ettirdi; MS 335''te ibadete açıldı. 1009''da yıkıldı ve 11. yüzyılda yeniden inşa edildi; Haçlılar 12. yüzyılda ona bugünkü görünümünün büyük bölümünü kazandırdı. Kabrin üzerindeki Edikül 2016–2017''de restore edildi.', 'Kilisenin bakımı, 1852 Statükosu uyarınca Rum Ortodoks, Roma Katolik (Fransisken) ve Ermeni Apostolik kiliselerince paylaşılır; Kıpti, Etiyopya ve Süryani Ortodoks topluluklarının da burada şapelleri vardır. Kapıları her sabah, anahtarları yüzyıllardır saklayan Müslüman aileler tarafından açılır.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
