INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'tr', 'İsrail ve çevre bölgelerdeki Hristiyan miras alanlarını, eserlerini ve el yazmalarını fotoğraflamaya, taramaya ve belgelemeye yönelik kapsamlı bir girişim. Bu dijital arşiv, araştırmacılar ve gelecek nesiller için paha biçilmez tarihi kayıtları koruyacaktır.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'tr', 'Kutsal Topraklar genelinde Hristiyan miras alanlarının dijital olarak belgelenmesi.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
