INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'uk', 'Реставрація', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'uk', 'Проєкт має на меті розв’язати нагальні реставраційні завдання базиліки: ремонт конструкцій, очищення фасаду та збереження автентичних архітектурних елементів. Роботи забезпечать безпеку й доступність будівлі для майбутніх поколінь.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'uk', 'Реставрація головної нави та фасаду Базиліки Благовіщення.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'uk', 'Реставрація базиліки — етап 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'uk', 'Документування', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'uk', 'Масштабна ініціатива з фотографування, сканування та документування пам’яток християнської спадщини, артефактів і рукописів в Ізраїлі та сусідніх регіонах. Цей цифровий архів збереже безцінні історичні свідчення для дослідників і майбутніх поколінь.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'uk', 'Цифрове документування пам’яток християнської спадщини по всій Святій Землі.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'uk', 'Документування спадщини Святої Землі', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'vi', 'Vương cung thánh đường Truyền Tin là một nhà thờ Công giáo tại Nazareth, Israel. Đây là một trong những nhà thờ lớn nhất Trung Đông và đánh dấu nơi mà theo truyền thống, Tổng lãnh thiên thần Gabriel đã loan báo cho Đức Maria rằng Mẹ sẽ sinh hạ Chúa Giêsu.', 'Vương cung thánh đường hiện nay được xây dựng năm 1969, do kiến trúc sư người Ý Giovanni Muzio thiết kế. Công trình tọa lạc trên nền các nhà thờ thời Byzantine và Thập tự chinh trước đó. Địa điểm này đã là nơi hành hương của Kitô hữu từ thời cổ đại.', 'Nhà thờ phục vụ cộng đoàn Công giáo địa phương tại Nazareth và chào đón những người hành hương từ khắp nơi trên thế giới. Thánh lễ được cử hành thường xuyên bằng nhiều ngôn ngữ.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'vi', 'Nhà thờ Giáng Sinh tại Bethlehem tọa lạc trên hang đá mà truyền thống Kitô giáo từ thế kỷ 2 đã tôn kính là nơi Chúa Giêsu sinh ra. Đây là một trong những nhà thờ được sử dụng liên tục lâu đời nhất trên thế giới và là Di sản Thế giới được UNESCO công nhận.', 'Vương cung thánh đường đầu tiên được Hoàng đế Constantine và mẹ ngài là Helena cho xây dựng vào khoảng năm 327 sau Công nguyên. Sau khi bị hư hại vào thế kỷ 6, Hoàng đế Justinian đã tái thiết công trình với quy mô lớn hơn, và phần lớn nhà thờ ngày nay có từ lần tái thiết đó. Các bức tranh khảm và những cột được vẽ trang trí từ thời Thập tự chinh vẫn còn được lưu giữ bên trong.', 'Nhà thờ được chia sẻ giữa các cộng đoàn Chính Thống giáo Hy Lạp, Công giáo Rôma (Dòng Phanxicô) và Tông truyền Armenia theo thỏa thuận Status Quo mang tính lịch sử. Các gia đình Kitô hữu địa phương ở Bethlehem cùng cầu nguyện tại đây với những người hành hương từ khắp nơi trên thế giới, đặc biệt vào dịp Giáng Sinh.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'vi', 'Nhà thờ Mộ Thánh trong Khu Phố Cổ Jerusalem chứa đựng hai nơi thánh thiêng nhất của Kitô giáo: đồi Golgotha, nơi Chúa Giêsu chịu đóng đinh, và ngôi mộ nơi Người được an táng và phục sinh, theo truyền thống.', 'Hoàng đế Constantine đã xây dựng nhà thờ đầu tiên tại đây vào thế kỷ 4; nhà thờ được cung hiến năm 335 sau Công nguyên. Công trình bị phá hủy năm 1009 và được xây dựng lại vào thế kỷ 11, và quân Thập tự chinh đã tạo nên phần lớn diện mạo hiện nay vào thế kỷ 12. Ngôi nhà nguyện nhỏ (Edicule) trên mộ đã được trùng tu vào năm 2016–2017.', 'Việc coi sóc nhà thờ được chia sẻ giữa các Giáo hội Chính Thống giáo Hy Lạp, Công giáo Rôma (Dòng Phanxicô) và Tông truyền Armenia, cùng với các cộng đoàn Chính Thống giáo Copt, Ethiopia và Syriac cũng có nhà nguyện riêng, theo thỏa thuận Status Quo năm 1852. Mỗi sáng, cửa nhà thờ được mở bởi những gia đình Hồi giáo đã gìn giữ chìa khóa qua nhiều thế kỷ.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
