INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', 'ee7631c8-fb98-4e45-b8ea-9fa78251cd23', 'content', 'vi', 'Chúng tôi đã tư liệu hóa thành công 50 di sản đầu tiên bằng ảnh chụp độ phân giải cao và quét 3D.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
