INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'vi', 'Trùng tu', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'vi', 'Dự án này tập trung vào những nhu cầu trùng tu cấp thiết của vương cung thánh đường, bao gồm sửa chữa kết cấu, làm sạch mặt tiền và bảo tồn các yếu tố kiến trúc nguyên bản. Công việc này sẽ bảo đảm công trình luôn an toàn và dễ tiếp cận cho các thế hệ mai sau.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'vi', 'Trùng tu gian giữa chính và mặt tiền của Vương cung thánh đường Truyền Tin.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'vi', 'Trùng tu Vương cung thánh đường - Giai đoạn 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'vi', 'Tư liệu hóa', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'vi', 'Một sáng kiến toàn diện nhằm chụp ảnh, quét và ghi lại các di sản, hiện vật và bản thảo Kitô giáo trên khắp Israel và các vùng lân cận. Kho lưu trữ kỹ thuật số này sẽ gìn giữ những tư liệu lịch sử vô giá cho các nhà nghiên cứu và các thế hệ mai sau.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'vi', 'Tư liệu hóa kỹ thuật số các di sản Kitô giáo khắp Đất Thánh.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'vi', 'Tư liệu hóa di sản Đất Thánh', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'zh', '天使报喜堂是位于以色列拿撒勒的一座天主教堂，也是中东地区最大的教堂之一。按照传统，这里正是天使长加百列向玛利亚报喜、告诉她将要生下耶稣的地方。', '现今的教堂建于1969年，由意大利建筑师乔瓦尼·穆齐奥设计，坐落在早期拜占庭时期和十字军时期教堂的遗址之上。自古以来，这里就是基督徒的朝圣之地。', '教堂服务于拿撒勒当地的天主教团体，也欢迎来自世界各地的朝圣者。这里定期以多种语言举行弥撒。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'zh', '伯利恒的主诞堂建在一座岩洞之上，自2世纪起，基督教传统便尊此洞为耶稣的诞生之地。它是世界上持续使用至今的最古老教堂之一，也是联合国教科文组织世界遗产。', '第一座教堂由君士坦丁大帝及其母亲海伦娜于公元327年前后下令兴建。6世纪时教堂遭到损毁，查士丁尼皇帝随后以更大的规模将其重建，今天教堂的大部分建筑即源于那次重建。堂内至今仍保存着十字军时期的马赛克和彩绘石柱。', '根据历史上的现状协定，教堂由希腊正教会、罗马天主教（方济各会）和亚美尼亚使徒教会三个团体共同使用。伯利恒当地的基督徒家庭与来自世界各地的朝圣者一同在此礼拜，圣诞节期间尤为如此。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'zh', '位于耶路撒冷老城的圣墓教堂内有基督教最神圣的两处圣地：一是耶稣被钉十字架的各各他，二是按照传统耶稣被埋葬并从死里复活的墓穴。', '君士坦丁大帝于4世纪在此建造了第一座教堂，并于公元335年举行祝圣。教堂于1009年被毁，11世纪得以重建；12世纪，十字军赋予了它今天的大致面貌。墓穴上方的小堂于2016至2017年间完成修复。', '根据1852年的现状协定，教堂由希腊正教会、罗马天主教（方济各会）和亚美尼亚使徒教会共同照管，科普特正教会、埃塞俄比亚正教会和叙利亚正教会也各有自己的小堂。教堂大门每天清晨由穆斯林家族开启，数百年来，他们世代掌管着教堂的钥匙。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
